INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cnemri/google-genai-skills/deep-research', 'community', 'cnemri', 'google-genai-skills', 'cnemri/google-genai-skills', 'deep-research', 0, 0, 60, '2026-02-18T01:08:43.456Z', '2026-02-18T07:19:17.512Z', NULL, '{"id":"cnemri/google-genai-skills/deep-research","name":"deep-research","description":{"zh":"深度研究技能允许开发者进行自主研究任务，包括规划、搜索、阅读和综合信息","ja":"ディープリサーチスキルは、開発者が自動研究タスクを実行できるようにします。計画、検索、読み取り、情報の統合が含まれます","ko":"딥 리서치 스킬은 개발자가 자율 연구 태스크를 수행할 수 있게 해줍니다. 계획, 검색, 읽기, 정보 통합이 포함됩니다","es":"El agente de investigación en profundidad de Gemini permite realizar tareas de investigación autónomas y precisas. Utiliza nuestra API de interacción para obtener resultados.","fr":"L''agent de recherche approfondie de Gemini permet de réaliser des tâches de recherche autonomes et précises. Utilisez notre API d''interaction pour obtenir des résultats.","de":"Der Deep-Research-Agent von Gemini ermöglicht die Durchführung autonomer und genauer Recherchen. Nutzen Sie unsere Interaktions-API, um Ergebnisse zu erhalten.","pt":"A habilidade de pesquisa profunda permite que os desenvolvedores realizem tarefas de pesquisa autônoma, planejando, buscando e sintetizando informações.","ru":"Навык глубокого исследования позволяет разработчикам выполнять автономные исследовательские задачи, планируя, ища и синтезируя информацию.","ar":"تمكن مهارة البحث العميق المطورين من إجراء مهام بحث ذاتي، والتخطيط والبحث ودمج المعلومات.","en":""},"seo":{"title":{"zh":"深度研究技能 - 自主研究任务","ja":"ディープリサーチスキル - 自動研究タスク","ko":"딥 리서치 스킬 - 자율 연구 태스크","es":"Investigación en profundidad con Gemini","fr":"Recherche approfondie avec Gemini","de":"Tiefere Recherche mit Gemini","pt":"Pesquisa Profunda: Tarefas de Pesquisa Autônoma","ru":"Глубокое Исследование: Автономные Исследовательские Задачи","ar":"البحث العميق: مهام البحث الذاتي","en":"deep-research"},"description":{"z