INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RefoundAI/lenny-skills/vibe-coding', 'community', 'RefoundAI', 'lenny-skills', 'RefoundAI/lenny-skills', 'vibe-coding', 0, 0, 30, '2026-02-18T01:08:43.456Z', '2026-02-18T07:19:14.994Z', NULL, '{"id":"RefoundAI/lenny-skills/vibe-coding","name":"vibe-coding","description":{"zh":"Vibe Coding AI","ja":"Vibe  AI","ko":"Vibe  AI","es":"Vibe Coding es una habilidad que ayuda a los desarrolladores a crear software utilizando herramientas de IA y lenguaje natural","fr":"Vibe Coding est une compétence qui aide les développeurs à créer des logiciels en utilisant des outils d''IA et du langage naturel","de":"Vibe Coding ist eine Fähigkeit, die Entwicklern hilft, Software mit KI-Tools und natürlicher Sprache zu erstellen","pt":"Vibe coding é uma abordagem de desenvolvimento de software que utiliza ferramentas de IA e linguagem natural para criar aplicações.","ru":"Vibe coding - это подход к разработке программного обеспечения, который использует инструменты ИИ и естественный язык для создания приложений.","ar":"ڤايب كودينج هو نهج لتطوير البرمجيات يعتمد على أدوات الذكاء الاصطناعي واللغة الطبيعية لإنشاء التطبيقات.","en":"86 product management skills from Lenny''s Podcast for Claude Code and AI agents. Hiring, user research, strategy, shipping, and more."},"seo":{"title":{"zh":"Vibe Coding","ja":"Vibe ","ko":"Vibe ","es":"Vibe Coding: Desarrollo de Software con IA","fr":"Vibe Coding: Développement de Logiciels avec l''IA","de":"Vibe Coding: Softwareentwicklung mit KI","pt":"Vibe Coding: Desenvolvimento de Software com IA","ru":"Vibe Coding: Разработка Программного Обеспечения с ИИ","ar":"ڤايب كودينج: تطوير البرمجيات باستخدام الذكاء الاصطناعي","en":"vibe-coding"},"description":{"zh":"Vibe Coding AI","ja":"Vibe  AI","ko":"Vibe  AI","es":"Vibe Coding es una habilidad que ayuda a los desarrolladores a crear software utilizando herramientas de IA y lenguaje natural","fr":"Vibe Coding est une compétence qui aide les développeurs à créer des logiciels en utilisant des outils d''IA et du langage naturel","de":"Vibe Coding ist eine Fähigkeit, die Entwicklern hilft, Software mit KI-Tools und natürlicher Sprache zu erstellen","pt":"Vibe coding é uma abordagem de desenvolvimento de software que utiliza ferramentas de IA e linguagem natural para criar aplicações.","ru":"Vibe coding - это подход к разработке программного обеспечения, который использует инструменты ИИ и естественный язык для создания приложений.","ar":"ڤايب كودينج هو نهج لتطوير البرمجيات يعتمد على أدوات الذكاء الاصطناعي واللغة الطبيعية لإنشاء التطبيقات.","en":"86 product management skills from Lenny''s Podcast for Claude Code and AI agents. Hiring, user research, strategy, shipping, and more."},"definition":{"en":"86 product management skills from Lenny''s Podcast for Claude Code and AI agents. Hiring, user research, strategy, shipping, and more."},"features":{"zh":["AI","3","API","SDK","CLI"],"ja":["AI","3","API","SDK","CLI"],"ko":["AI","3","API","SDK","CLI"],"es":["Desarrollo de software con herramientas de IA","Uso de lenguaje natural para crear código","Guía para dividir problemas en piezas más pequeñas","Configuración de expectativas para proyectos de desarrollo","Integración con frameworks y conocimientos de líderes de productos"],"fr":["Développement de logiciels avec des outils d''IA","Utilisation du langage naturel pour créer du code","Guide pour diviser les problèmes en morceaux plus petits","Configuration des attentes pour les projets de développement","Intégration avec des frameworks et des connaissances de leaders de produits"],"de":["Softwareentwicklung mit KI-Tools","Verwendung von natürlicher Sprache zum Erstellen von Code","Anleitung zur Aufteilung von Problemen in kleinere Teile","Konfiguration von Erwartungen für Entwicklungsprojekte","Integration mit Frameworks und Kenntnissen von Produktleitern"],"pt":["Desenvolvimento de software com IA","Uso de linguagem natural","Criação de protótipos","Desenvolvimento de aplicações","Integração com frameworks","Otimização de processos"],"ru":["Разработка программного обеспечения с ИИ","Использование естественного языка","Создание прототипов","Разработка приложений","Интеграция с фреймворками","Оптимизация процессов"],"ar":["تطوير البرمجيات باستخدام الذكاء الاصطناعي","استخدام اللغة الطبيعية","إنشاء نماذج أولية","تطوير التطبيقات","التكامل مع الإطارات","تحسين العمليات"]},"keywords":{"zh":["Vibe Coding","AI","API","SDK","CLI","AI","AI"],"ja":["Vibe ","AI","API","SDK","CLI","AI","AI"],"ko":["Vibe ","AI","API","SDK","CLI","AI","AI"],"es":["vibe coding","desarrollo de software","herramientas de IA","lenguaje natural","frameworks de desarrollo","líderes de productos","desarrollo de aplicaciones","prototipado"],"fr":["vibe coding","développement de logiciels","outils d''IA","langage naturel","frameworks de développement","leaders de produits","développement d''applications","création de prototypes"],"de":["vibe coding","softwareentwicklung","KI-Tools","natürliche Sprache","frameworks für die Entwicklung","Produktleiter","Anwendungsentwicklung","Prototyping"],"pt":["vibe coding","desenvolvimento de software","IA","linguagem natural","prototipagem","desenvolvimento de aplicações","frameworks","otimização de processos"],"ru":["vibe coding","разработка программного обеспечения","ИИ","естественный язык","прототипирование","разработка приложений","фреймворки","оптимизация процессов"],"ar":["ڤايب كودينج","تطوير البرمجيات","الذكاء الاصطناعي","اللغة الطبيعية","إنشاء نماذج أولية","تطوير التطبيقات","الإطارات","تحسين العمليات"]}},"owner":"RefoundAI","repo":"lenny-skills","repoPath":"RefoundAI/lenny-skills","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.456Z","topics":[],"category":"community","skillMd":{"name":"vibe-coding","description":"Help users build software using AI coding tools. Use when someone is using AI to generate code, building prototypes without deep technical skills, or exploring how non-engineers can create functional software through natural language.","bodyPreview":"# Vibe Coding\n\nHelp the user build software using AI tools and natural language, using frameworks and insights from 3 product leaders.\n\n## How to Help\n\nWhen the user asks for help with vibe coding:\n\n1. **Understand the goal** - Ask what they''re trying to build and who it''s for (prototype, internal tool, production app)\n2. **Guide the approach** - Help them break down the problem into smaller pieces for iterative AI prompts\n3. **Set expectations** - Discuss what vibe coding is good for (prototype","body":"# Vibe Coding\n\nHelp the user build software using AI tools and natural language, using frameworks and insights from 3 product leaders.\n\n## How to Help\n\nWhen the user asks for help with vibe coding:\n\n1. **Understand the goal** - Ask what they''re trying to build and who it''s for (prototype, internal tool, production app)\n2. **Guide the approach** - Help them break down the problem into smaller pieces for iterative AI prompts\n3. **Set expectations** - Discuss what vibe coding is good for (prototypes, MVPs) versus when professional engineering is needed\n4. **Coach on iteration** - Help them understand how to refine output through follow-up prompts\n\n## Core Principles\n\n### Vibe coding is a new skill\nElena Verna: \"I vibe code myself so I would put that as even as a skill on my resume now.\" This is a distinct, transformative skill for non-technical roles - PMs, marketers, designers - to build functional software using natural language.\n\n### Replace Figma with prototypes\nKevin Weil: \"Instead of showing stuff in Figma, we should be showing prototypes that people are vibe coding over the course of 30 minutes to illustrate proofs of concept.\" Functional code prototypes can be built in the time it takes to create static mockups.\n\n### Build tools to build tools\nAlexander Embiricos: \"They''ll vibe code an animation editor and then they use the animation editor to build the animation.\" Non-engineers can now build functional software and custom tools without deep technical mastery.\n\n### Go beyond prompt engineering\nVibe coding is not just writing prompts - it''s iteratively building functional software through conversation with AI. It requires understanding how to break problems down, test outputs, and refine through follow-up.\n\n### Know the limits\nVibe-coded software is great for prototypes, internal tools, and MVPs. Production-grade systems with complex requirements still need professional engineering review.\n\n## Questions to Help Users\n\n- \"What are you trying to build, and who will use it?\"\n- \"Is this a throwaway prototype or something that needs to scale?\"\n- \"Can you break this down into smaller pieces to build incrementally?\"\n- \"What''s the simplest version that would let you test your hypothesis?\"\n- \"Have you tried describing what''s not working and asking the AI to fix it?\"\n- \"Do you need this to be production-grade, or is it okay if it''s rough?\"\n\n## Common Mistakes to Flag\n\n- **Trying to build everything at once** - Break complex projects into smaller, iterative builds\n- **Not testing the output** - Always run and test what the AI generates; don''t assume it works\n- **Expecting production quality** - Vibe-coded apps are great for validation but may need engineering for production\n- **Unclear specifications** - The clearer your description of what you want, the better the output\n- **Giving up after one try** - Vibe coding is iterative; refine through follow-up prompts\n\n## Deep Dive\n\nFor all 3 insights from 3 guests, see `references/guest-insights.md`\n\n## Related Skills\n\n- Writing PRDs\n- Usability Testing\n- Building with LLMs\n- Shipping Products\n"},"lastSynced":"2026-02-18T07:19:14.994Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Claude Code and AutoGPT needing human-centered software development capabilities through natural language and iterative prompts.","zh":"非常适合需要通过自然语言和迭代提示进行人性化软件开发能力的AI代理，如Claude Code和AutoGPT。","ja":"Claude CodeやAutoGPTのような、自然言語とイテレーティブなプロンプトを通じてヒューマンセントリックなソフトウェア開発能力を必要とするAIエージェントに最適です。","ko":"클라우드 코드와 오토GPT 같은 자연어와 반복적인 프롬프트를 통해 인간 중심의 소프트웨어 개발 능력을 필요로 하는 AI 에이전트에게 최적입니다.","es":"Perfecto para agentes de IA como Claude Code y AutoGPT que necesitan capacidades de desarrollo de software centradas en humanos a través de lenguaje natural y solicitudes iterativas.","fr":"Parfait pour les agents IA comme Claude Code et AutoGPT ayant besoin de capacités de développement de logiciels axées sur l''homme via le langage naturel et les invites itératives.","de":"Perfekt für KI-Agents wie Claude Code und AutoGPT, die menschenzentrierte Software-Entwicklungs-Fähigkeiten durch natürliche Sprache und iterative Anfragen benötigen.","pt":"Perfeito para agentes de IA como Claude Code e AutoGPT que necessitam de capacidades de desenvolvimento de software centradas no ser humano por meio de linguagem natural e prompts iterativos.","ru":"Идеально подходит для агентов ИИ, таких как Claude Code и AutoGPT, которым необходимы возможности разработки программного обеспечения, ориентированные на человека, через естественный язык и итеративные подсказки.","ar":"مثالي لعمليات الوكيل الذكي مثل Claude Code و AutoGPT التي تحتاج إلى قدرات تطوير البرمجيات المتمركزة حول الإنسان من خلال اللغة الطبيعية والتحفيزات التكرارية."},"recommendation":{"en":"Empowers agents to break down complex software development problems into smaller pieces using frameworks and insights from product leaders, facilitating effective vibe coding for prototype, internal tool, or production app development using natural language processing and AI tools.","zh":"赋予代理人将复杂的软件开发问题分解为较小的部分的能力，使用产品领导者的框架和见解，促进自然语言处理和AI工具的有效使用，以便进行原型、内部工具或生产应用的开发。","ja":"プロダクトリーダーのフレームワークとインサイトを使用して、複雑なソフトウェア開発問題をより小さな部分に分解する能力をエージェントに与え、自然言語処理とAIツールの効果的な使用を促進して、プロトタイプ、内部ツール、またはプロダクションアプリの開発を行う。","ko":"제품 리더의 프레임워크와 통찰력을 사용하여 복잡한 소프트웨어 개발 문제를 더 작은 부분으로 나누는 능력을 에이전트에게 부여하여 자연어 처리와 AI 도구의 효과적인 사용을 촉진하여 프로토타입, 내부 도구 또는 생산 애플리케이션 개발을 수행합니다.","es":"Habilita a los agentes a descomponer problemas de desarrollo de software complejos en piezas más pequeñas utilizando marcos y conocimientos de líderes de producto, facilitando la codificación de vibración efectiva para el desarrollo de prototipos, herramientas internas o aplicaciones de producción utilizando el procesamiento de lenguaje natural y herramientas de IA.","fr":"Permet aux agents de décomposer des problèmes de développement de logiciels complexes en plus petites parties en utilisant des cadres et des connaissances de leaders de produit, facilitant ainsi la codification de vibration efficace pour le développement de prototypes, d''outils internes ou d''applications de production en utilisant le traitement du langage naturel et les outils d''IA.","de":"Ermächtigt Agenten, komplexe Software-Entwicklungsprobleme in kleinere Teile zu zerlegen, indem sie Frameworks und Erkenntnisse von Produktleitern verwenden, wodurch eine effektive Vibro-Codierung für die Entwicklung von Prototypen, internen Tools oder Produktions-Apps unter Verwendung von natürlicher Sprachverarbeitung und KI-Tools erleichtert wird.","pt":"Habilita os agentes a quebrar problemas complexos de desenvolvimento de software em peças menores usando estruturas e insights de líderes de produto, facilitando a codificação eficaz de vibração para desenvolvimento de protótipos, ferramentas internas ou aplicativos de produção usando processamento de linguagem natural e ferramentas de IA.","ru":"Наделяет агентов возможностью разбить сложные проблемы разработки программного обеспечения на более мелкие части с помощью рамок и инсайтов от лидеров продукта, что облегчает эффективную вибро-кодирование для разработки прототипов, внутренних инструментов или приложений для производства с помощью обработки естественного языка и инструментов ИИ.","ar":"تمكن الوكلاء من كسر مشاكل تطوير البرمجيات المعقدة إلى قطع صغيرة باستخدام الإطارات والرؤى من قادة المنتج، مما يسهل الترميز الفعال للاهتزاز لتطوير النماذج الأولية والأدوات الداخلية أو تطبيقات الإنتاج باستخدام معالجة اللغة الطبيعية وأدوات الذكاء الاصطناعي."},"useCases":{"en":["Guiding users through iterative AI prompts for software development","Breaking down complex problems into smaller, manageable pieces for vibe coding","Setting expectations for vibe coding applications and limitations"],"zh":["通过迭代的AI提示引导用户进行软件开发","将复杂问题分解为较小、可管理的部分以进行氛围编码","为氛围编码应用程序和限制设置期望"],"ja":["イテレーティブなAIプロンプトを使用してユーザーをソフトウェア開発に導く","複雑な問題をより小さな、管理可能な部分に分解してビブコーディングを行う","ビブコーディングアプリケーションと制限に対する期待を設定する"],"ko":["반복적인 AI 프롬프트를 사용하여 사용자를 소프트웨어 개발로 안내합니다.","복잡한 문제를 더 작은 부분으로 나누어 분위기 코딩을 수행합니다.","분위기 코딩 애플리케이션 및 제한에 대한 기대 설정"],"es":["Guiar a los usuarios a través de solicitudes de IA iterativas para el desarrollo de software","Descomponer problemas complejos en piezas más pequeñas y manejables para la codificación de vibración","Establecer expectativas para aplicaciones y limitaciones de codificación de vibración"],"fr":["Guider les utilisateurs à travers des invites IA itératives pour le développement de logiciels","Décomposer des problèmes complexes en pièces plus petites et gérables pour la codification de vibration","Définir les attentes pour les applications et les limites de la codification de vibration"],"de":["Benutzer durch iterative KI-Anfragen für die Software-Entwicklung führen","Komplexe Probleme in kleinere, handhabbare Teile für die Vibro-Codierung zerlegen","Erwartungen für Vibro-Codierungsanwendungen und -einschränkungen setzen"],"pt":["Orientar os usuários por meio de prompts de IA iterativos para desenvolvimento de software","Quebrar problemas complexos em peças menores e gerenciáveis para codificação de vibração","Definir expectativas para aplicações e limitações de codificação de vibração"],"ru":["Направлять пользователей через итеративные подсказки ИИ для разработки программного обеспечения","Разбить сложные проблемы на более мелкие и управляемые части для вибро-кодирования","Установить ожидания для приложений и ограничений вибро-кодирования"],"ar":["توجيه المستخدمين من خلال تحفيزات الذكاء الاصطناعي التكرارية لتطوير البرمجيات","كسر المشاكل المعقدة إلى قطع صغيرة وقابلة للإدارة للترميز الاهتزازي","تحديد التوقعات للتطبيقات والمحددات للترميز الاهتزازي"]},"limitations":{"en":["Requires understanding of software development goals and target audience","Dependent on the quality of user input and AI tool capabilities"],"zh":["需要了解软件开发目标和目标受众","依赖于用户输入质量和AI工具能力"],"ja":["ソフトウェア開発の目標とターゲットオーディエンスを理解する必要がある","ユーザー入力の質とAIツールの能力に依存する"],"ko":["소프트웨어 개발 목표와 대상 사용자를 이해해야 함","사용자 입력의 품질과 AI 도구의 능력에 의존"],"es":["Requiere comprensión de los objetivos de desarrollo de software y del público objetivo","Dependiente de la calidad de la entrada del usuario y de las capacidades de las herramientas de IA"],"fr":["Nécessite une compréhension des objectifs de développement de logiciels et du public cible","Dépendante de la qualité de la saisie de l''utilisateur et des capacités des outils d''IA"],"de":["Benötigt Verständnis für Software-Entwicklungsziele und Zielgruppe","Abhängig von der Qualität der Benutzereingabe und den Fähigkeiten der KI-Tools"],"pt":["Exige compreensão dos objetivos de desenvolvimento de software e do público-alvo","Depende da qualidade da entrada do usuário e das capacidades das ferramentas de IA"],"ru":["Требует понимания целей разработки программного обеспечения и целевой аудитории","Зависит от качества входных данных пользователя и возможностей инструментов ИИ"],"ar":["يتطلب فهم أهداف تطوير البرمجيات وجمهور الهدف","يعتمد على جودة مدخلات المستخدم وقدرات أدوات الذكاء الاصطناعي"]},"version":3},"qualityScore":30}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('partme-ai/full-stack-skills/nextjs', 'community', 'partme-ai', 'full-stack-skills', 'partme-ai/full-stack-skills', 'nextjs', 0, 0, 40, '2026-02-18T01:08:43.456Z', '2026-02-18T07:19:42.863Z', NULL, '{"id":"partme-ai/full-stack-skills/nextjs","name":"nextjs","description":{"zh":"Next.js 技术技能提供了全栈开发所需的功能，包括路由、数据获取、缓存和部署","ja":"Next.js 技術スキルは、フルスタック開発に必要な機能を提供します、ルーティング、データ取得、キャッシュ、デプロイなど","ko":"Next.js 기술 스킬은 풀스택 개발에 필요한 기능을 제공합니다, 라우팅, 데이터 가져오기, 캐싱, 배포 등","es":"Next.js es un framework para crear aplicaciones web de alta calidad. Ofrece funcionalidades como rutas, fetching de datos y caché.","fr":"Next.js est un framework pour créer des applications web de haute qualité. Il offre des fonctionnalités telles que les routes, le fetching de données et la mise en cache.","de":"Next.js ist ein Framework für die Erstellung von hochwertigen Webanwendungen. Es bietet Funktionen wie Routen, Datenabruf und Caching.","pt":"Next.js é um framework React para desenvolvimento de aplicações web escaláveis e de alto desempenho.","ru":"Next.js — это фреймворк React для разработки масштабируемых и высокопроизводительных веб-приложений.","ar":"Next.js هو إطار عمل React لتطوير التطبيقات القابلة للتوسعة والأداء العالي","en":"这是一个免费的全栈开发所需的技能市场，提供各种实用的 AI 技能集合，支持多种平台。"},"seo":{"title":{"zh":"Next.js 技术技能","ja":"Next.js 技術スキル","ko":"Next.js 기술 스킬","es":"Desarrollo con Next.js: Guía para desarrolladores","fr":"Développement avec Next.js : Guide pour les développeurs","de":"Entwicklung mit Next.js: Anleitung für Entwickler","pt":"Desenvolvimento de Aplicativos com Next.js","ru":"Разработка приложений с Next.js","ar":"تطوير التطبيقات باستخدام Next.js","en":"nextjs"},"description":{"zh":"Next.js 技术技能提供了全栈开发所需的功能，包括路由、数据获取、缓存和部署","ja":"Next.js 技術スキルは、フルスタック開発に必要な機能を提供します、ルーティング、データ取得、キャッシュ、デプロイなど","ko":"Next.js 기술 스킬은 풀스택 개발에 필요한 기능을 제공합니다, 라우팅, 데이터 가져오기, 캐싱, 배포 등","es":"Next.js es un framework para crear aplicaciones web de alta calidad. Ofrece funcionalidades como rutas, fetching de datos y caché.","fr":"Next.js est un framework pour créer des applications web de haute qualité. Il offre des fonctionnalités telles que les routes, le fetching de données et la m...","de":"Next.js ist ein Framework für die Erstellung von hochwertigen Webanwendungen. Es bietet Funktionen wie Routen, Datenabruf und Caching.","pt":"Next.js é um framework React para desenvolvimento de aplicações web escaláveis e de alto desempenho.","ru":"Next.js — это фреймворк React для разработки масштабируемых и высокопроизводительных веб-приложений.","ar":"Next.js هو إطار عمل React لتطوير التطبيقات القابلة للتوسعة والأداء العالي","en":"这是一个免费的全栈开发所需的技能市场，提供各种实用的 AI 技能集合，支持多种平台。"},"definition":{"en":"这是一个免费的全栈开发所需的技能市场，提供各种实用的 AI 技能集合，支持多种平台。"},"features":{"zh":["路由和页面管理","数据获取和缓存","部署和服务器配置","官方 API 和文档支持","多种平台支持"],"ja":["ルーティングとページ管理","データ取得とキャッシュ","デプロイとサーバー構成","公式 API とドキュメントのサポート","複数のプラットフォームのサポート"],"ko":["라우팅과 페이지 관리","데이터 가져오기와 캐싱","배포와 서버 구성","공식 API와 문서 지원","다중 플랫폼 지원"],"es":["Implementación de rutas","Fetching de datos","Caché","Despliegue","Compatibilidad con múltiples plataformas"],"fr":["Implémentation de routes","Fetching de données","Mise en cache","Déploiement","Compatibilité avec plusieurs plateformes"],"de":["Implementierung von Routen","Datenabruf","Caching","Deployment","Kompatibilität mit mehreren Plattformen"],"pt":["Rotas personalizadas","Busca de dados","Cache","Implantação","Documentação oficial"],"ru":["Пользовательские маршруты","Получение данных","Кэш","Развертывание","Официальная документация"],"ar":["مسارات مخصصة","استرجاع البيانات","التخزين المؤقت","النشر","التوثيق الرسمي"]},"keywords":{"zh":["Next.js","React 框架","服务器渲染","静态网站","路由管理","数据获取","缓存","部署","服务器配置"],"ja":["Next.js","React フレームワーク","サーバー側レンダリング","静的サイト","ルーティング管理","データ取得","キャッシュ","デプロイ","サーバー構成"],"ko":["Next.js","React 프레임워크","서버 사이드 렌더링","정적 사이트","라우팅 관리","데이터 가져오기","캐싱","배포","서버 구성"],"es":["Next.js","Desarrollo web","Aplicaciones web","Rutas","Fetching de datos","Caché","Despliegue"],"fr":["Next.js","Développement web","Applications web","Routes","Fetching de données","Mise en cache","Déploiement"],"de":["Next.js","Webentwicklung","Webanwendungen","Routen","Datenabruf","Caching","Deployment"],"pt":["Next.js","Desenvolvimento web","React","Rotas personalizadas","Busca de dados","Cache","Implantação"],"ru":["Next.js","Веб-разработка","React","Пользовательские маршруты","Получение данных","Кэш","Развертывание"],"ar":["Next.js","تطوير الويب","React","مسارات مخصصة","استرجاع البيانات","التخزين المؤقت","النشر"]}},"owner":"partme-ai","repo":"full-stack-skills","repoPath":"partme-ai/full-stack-skills","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.456Z","topics":[],"category":"community","skillMd":{"name":"nextjs","description":"Guidance for Next.js using the official docs at nextjs.org/docs. Use when the user needs Next.js concepts, configuration, routing, data fetching, or API reference details.","bodyPreview":"## When to use this skill\n\nUse this skill whenever the user wants to:\n- Follow Next.js documentation topics (App Router, Pages Router, architecture, community)\n- Implement Next.js routing, data fetching, caching, or deployment\n- Use official APIs and configuration options from the docs\n\n## How to use this skill\n\n1. **Identify the topic** from the user request.\n2. **Open the matching example file** in `examples/`.\n3. **Follow the official Next.js docs** linked in the file.\n\n## Mapping Rules (one-","body":"## When to use this skill\n\nUse this skill whenever the user wants to:\n- Follow Next.js documentation topics (App Router, Pages Router, architecture, community)\n- Implement Next.js routing, data fetching, caching, or deployment\n- Use official APIs and configuration options from the docs\n\n## How to use this skill\n\n1. **Identify the topic** from the user request.\n2. **Open the matching example file** in `examples/`.\n3. **Follow the official Next.js docs** linked in the file.\n\n## Mapping Rules (one-to-one with https://nextjs.org/docs)\n\nThe `examples/` directory mirrors the official docs structure:\n\n- `examples/index.md` → https://nextjs.org/docs\n- `examples/app/...` → https://nextjs.org/docs/app/...\n- `examples/pages/...` → https://nextjs.org/docs/pages/...\n- `examples/architecture/...` → https://nextjs.org/docs/architecture/...\n- `examples/community/...` → https://nextjs.org/docs/community/...\n\n**Path rule:**\n- Remove numeric prefixes from doc folders and filenames (e.g., `01-app` → `app`).\n- `index.mdx` pages map to `index.md` inside the corresponding directory.\n\n## Resources\n- Docs: https://nextjs.org/docs\n\n## Keywords\nNext.js, App Router, Pages Router, routing, data fetching, caching, server components, client components, middleware, deployment, configuration\n"},"lastSynced":"2026-02-18T07:19:42.863Z","agentAnalysis":{"suitability":{"en":"Ideal for Full Stack Agents needing advanced Next.js development capabilities for routing, data fetching, and deployment.","zh":"适合需要高级 Next.js 开发能力的全栈代理，包括路由、数据获取和部署。","ja":"Next.js のルーティング、データ取得、デプロイの高度な開発能力を必要とするフルスタックエージェントに最適です。","ko":"라우팅, 데이터 가져오기 및 배포를 포함한 고급 Next.js 개발 기능이 필요한 풀스택 에이전트에게 적합합니다.","es":"Ideal para Agentes de Full Stack que necesitan capacidades de desarrollo avanzadas de Next.js para enrutamiento, obtención de datos y despliegue.","fr":"Idéal pour les agents Full Stack ayant besoin de capacités de développement avancées Next.js pour le routage, la récupération de données et le déploiement.","de":"Ideal für Full-Stack-Agents, die erweiterte Next.js-Entwicklungsfähigkeiten für Routing, Datenabruf und Bereitstellung benötigen.","pt":"Ideal para Agentes Full Stack que precisam de capacidades avançadas de desenvolvimento Next.js para roteamento, busca de dados e implantação.","ru":"Идеально для агентов Full Stack, которым необходимы расширенные возможности разработки Next.js для маршрутизации, получения данных и развертывания.","ar":"مثالية لعميل الخدمة الكاملة الذين يحتاجون إلى قدرات متقدمة لتنمية Next.js لتحديد المسار والحصول على البيانات والتنصيب."},"recommendation":{"en":"Empowers agents to implement Next.js routing, data fetching, caching, and deployment using official APIs and configuration options, following the latest App Router and Pages Router documentation topics.","zh":"赋予代理实现 Next.js 路由、数据获取、缓存和部署的能力，使用官方 API 和配置选项，遵循最新的应用路由器和页面路由器文档主题。","ja":"公式 API および設定オプションを使用して、Next.js ルーティング、データ取得、キャッシュ、デプロイを実装するエージェントを強化します。最新のアプリ ルータおよびページ ルータのドキュメント トピックに従います。","ko":"공식 API 및 구성 옵션을 사용하여 Next.js 라우팅, 데이터 가져오기, 캐싱 및 배포를 구현할 수 있는 에이전트를 강화합니다. 최신 애플리케이션 라우터 및 페이지 라우터 문서 주제를 따릅니다.","es":"Habilita a los agentes a implementar el enrutamiento de Next.js, la obtención de datos, la memorización en caché y el despliegue utilizando API oficiales y opciones de configuración, siguiendo los temas de documentación más recientes de App Router y Pages Router.","fr":"Permet aux agents de mettre en œuvre le routage Next.js, la récupération de données, la mise en cache et le déploiement en utilisant les API officielles et les options de configuration, en suivant les derniers sujets de documentation d''App Router et de Pages Router.","de":"Ermächtigt die Agenten, Next.js-Routing, Datenabruf, Caching und Bereitstellung mithilfe offizieller APIs und Konfigurationsmöglichkeiten zu implementieren, unter Berücksichtigung der neuesten Dokumentationsthemen zu App Router und Pages Router.","pt":"Permite que os agentes implementem o roteamento Next.js, a busca de dados, o cache e o deploy utilizando as APIs oficiais e as opções de configuração, seguindo os tópicos de documentação mais recentes do App Router e Pages Router.","ru":"Наделяет агентов возможностью реализовать маршрутизацию Next.js, получение данных, кэширование и развертывание, используя официальные API и опции конфигурации, следуя последним темам документации App Router и Pages Router.","ar":"تمكّن الوكلاء من تنفيذ تحديد مسار Next.js والحصول على البيانات والแคش والتنصيب باستخدام واجهات برمجة التطبيقات الرسمية وخيارات التهيئة، متبعة مواضيع توثيق App Router و Pages Router الأخيرة."},"useCases":{"en":["Implementing App Router for dynamic routing","Optimizing data fetching with caching mechanisms","Deploying Next.js applications with official configuration options"],"zh":["实现 App Router 的动态路由","使用缓存机制优化数据获取","使用官方配置选项部署 Next.js 应用程序"],"ja":["アプリ ルーターの動的ルーティングの実装","キャッシュ メカニズムを使用したデータ取得の最適化","公式の設定オプションを使用した Next.js アプリケーションのデプロイ"],"ko":["동적 라우팅을 위한 애플리케이션 라우터 구현","캐싱 메커니즘을 사용한 데이터 가져오기 최적화","공식 구성 옵션을 사용한 Next.js 애플리케이션 배포"],"es":["Implementar App Router para enrutamiento dinámico","Optimizar la obtención de datos con mecanismos de caché","Desplegar aplicaciones Next.js con opciones de configuración oficiales"],"fr":["Mettre en œuvre App Router pour un routage dynamique","Optimiser la récupération de données avec des mécanismes de mise en cache","Déployer des applications Next.js avec des options de configuration officielles"],"de":["App Router für dynamisches Routing implementieren","Datenabruf mit Cachemechanismen optimieren","Next.js-Anwendungen mit offiziellen Konfigurationsmöglichkeiten bereitstellen"],"pt":["Implementar o App Router para roteamento dinâmico","Otimizar a busca de dados com mecanismos de cache","Implantar aplicações Next.js com opções de configuração oficiais"],"ru":["Реализовать App Router для динамического маршрутизации","Оптимизировать получение данных с помощью механизмов кэширования","Развертывать приложения Next.js с официальными опциями конфигурации"],"ar":["تنفيذ App Router لتحديد المسار الديناميكي","تحسين الحصول على البيانات باستخدام آليات الكاش","تنصيب تطبيقات Next.js بخيارات التهيئة الرسمية"]},"limitations":{"en":["Requires knowledge of Next.js documentation and APIs","Limited to Next.js framework and its ecosystem"],"zh":["需要了解 Next.js 文档和 API","仅限 Next.js 框架及其生态系统"],"ja":["Next.js ドキュメントおよび API の知識が必要","Next.js フレームワークおよびそのエコシステムに限定"],"ko":["Next.js 문서 및 API에 대한 지식이 필요합니다","Next.js 프레임워크 및その 에코시스템에 한정"],"es":["Requiere conocimiento de la documentación y las API de Next.js","Limitado al marco de Next.js y su ecosistema"],"fr":["Nécessite une connaissance de la documentation et des API de Next.js","Limité au framework Next.js et à son écosystème"],"de":["Benötigt Kenntnisse der Next.js-Dokumentation und -APIs","Begrenzt auf das Next.js-Framework und sein Ökosystem"],"pt":["Exige conhecimento da documentação e das APIs do Next.js","Limitado ao framework Next.js e seu ecossistema"],"ru":["Требует знания документации и API Next.js","Ограничен фреймворком Next.js и его экосистемой"],"ar":["يتطلب معرفة توثيق واجهات برمجة التطبيقات Next.js","محدود بإطار العمل Next.js ونظامه البيئي"]},"version":3},"qualityScore":40}');
