INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aiskillstore/marketplace/unity-editor', 'community', 'aiskillstore', 'marketplace', 'aiskillstore/marketplace', 'unity-editor', 0, 0, 80, '2026-02-18T01:08:43.456Z', '2026-02-18T07:23:49.187Z', NULL, '{"id":"aiskillstore/marketplace/unity-editor","name":"unity-editor","description":{"zh":"Unityctl 是一个安全审计的技能，允许您从命令行远程控制 Unity 编辑器","ja":"Unityctl はセキュリティ監査済みのスキルで、コマンドラインから Unity エディターをリモート制御できる","ko":"유니티 CTL은 보안 감사를 통과한 스킬로 명령줄에서 유니티 에디터를 원격 제어할 수 있다","es":"El controlador remoto de Unity Editor permite controlar el editor desde la línea de comandos. Utiliza unityctl para refresh assets y más","fr":"Le contrôle à distance de l''éditeur Unity permet de contrôler l''éditeur depuis la ligne de commande. Utilisez unityctl pour rafraîchir les assets et plus","de":"Die Fernbedienung des Unity-Editors ermöglicht die Steuerung des Editors von der Kommandozeile aus. Verwenden Sie unityctl, um Assets zu aktualisieren und mehr","pt":"O unityctl permite controlar o Unity Editor de forma remota, sem modo de lote. Aprenda a configurar e utilizar.","ru":"Утилита unityctl позволяет управлять редактором Unity удаленно, без режима пакетной обработки. Узнайте, как настроить и использовать.","ar":"يوفر لك unityctl khảية التحكم في محرر يونيتي عن بعد, بدون وضع المجموعة. تعلم كيفية الضبط والاستخدام.","en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"seo":{"title":{"zh":"Unity 编辑器远程控制","ja":"Unity エディター リモート制御","ko":"유니티 에디터 원격 제어","es":"Controlador Remoto de Unity Editor","fr":"Contrôle à Distance de l''Éditeur Unity","de":"Unity-Editor-Fernbedienung","pt":"Controle Remoto do Unity Editor","ru":"Удаленный контроль редактора Unity","ar":"التحكم عن بعد لمحرر يونيتي","en":"unity-editor"},"description":{"zh":"Unityctl 是一个安全审计的技能，允许您从命令行远程控制 Unity 编辑器","ja":"Unityctl はセキュリティ監査済みのスキルで、コマンドラインから Unity エディターをリモート制御できる","ko":"유니티 CTL은 보안 감사를 통과한 스킬로 명령줄에서 유니티 에디터를 원격 제어할 수 있다","es":"El controlador remoto de Unity Editor permite controlar el editor desde la línea de comandos. Utiliza unityctl para refresh assets y más","fr":"Le contrôle à distance de l''éditeur Unity permet de contrôler l''éditeur depuis la ligne de commande. Utilisez unityctl pour rafraîchir les assets et plus","de":"Die Fernbedienung des Unity-Editors ermöglicht die Steuerung des Editors von der Kommandozeile aus. Verwenden Sie unityctl, um Assets zu aktualisieren und mehr","pt":"O unityctl permite controlar o Unity Editor de forma remota, sem modo de lote. Aprenda a configurar e utilizar.","ru":"Утилита unityctl позволяет управлять редактором Unity удаленно, без режима пакетной обработки. Узнайте, как настроить и использовать.","ar":"يوفر لك unityctl khảية التحكم في محرر يونيتي عن بعد, بدون وضع المجموعة. تعلم كيفية الضبط والاستخدام.","en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"definition":{"en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"features":{"zh":["远程控制 Unity 编辑器","无需批处理模式","一键安装和质量验证","支持脚本修改后的资产刷新"],"ja":["Unity エディターのリモート制御","バッチモード不要","ワンクリックインストールと品質検証","スクリプト変更後のアセット更新をサポート"],"ko":["유니티 에디터 원격 제어","배치 모드 필요 없음","원클릭 설치 및 품질 검증","스크립트 변경 후 자산 갱신 지원"],"es":["Control remoto del editor de Unity","Refresh de assets después de cambios en scripts","Verificación de conexión","Lanzamiento de Unity desde la línea de comandos","Compilación de assets con errores de directorio"],"fr":["Contrôle à distance de l''éditeur Unity","Rafraîchissement des assets après modification de scripts","Vérification de connexion","Lancement de Unity depuis la ligne de commande","Compilation des assets avec erreurs de répertoire"],"de":["Fernbedienung des Unity-Editors","Aktualisierung von Assets nach Skriptänderungen","Verbindungüberprüfung","Starten von Unity von der Kommandozeile aus","Kompilierung von Assets mit Verzeichnisfehlern"],"pt":["Controle remoto do Unity Editor","Instalação de um clique","Verificação de qualidade","Controle da compilação de ativos","Verificação de status da conexão","Atualização de ativos após alterações nos scripts"],"ru":["Удаленный контроль редактора Unity","Однократная установка","Проверка качества","Управление компиляцией активов","Проверка статуса соединения","Обновление активов после изменений в скриптах"],"ar":["التحكم عن بعد لمحرر يونيتي","تثبيت في خطوة واحدة","مراجعة الجودة","التحكم في تجميع الأصول","مراجعة حالة الاتصال","تحديث الأصول بعد تغييرات في البرامج النصية"]},"keywords":{"zh":["Unity 编辑器","远程控制","命令行工具","Unityctl","脚本修改","资产刷新","游戏开发","Unity 开发"],"ja":["Unity エディター","リモート制御","コマンドラインツール","Unityctl","スクリプト変更","アセット更新","ゲーム開発","Unity 開発"],"ko":["유니티 에디터","원격 제어","명령줄 툴","유니티 CTL","스크립트 변경","자산 갱신","게임 개발","유니티 개발"],"es":["unity editor","control remoto","unityctl","refresh assets","compilación de assets","desarrollo de juegos","herramientas de desarrollo","unity developer"],"fr":["éditeur Unity","contrôle à distance","unityctl","rafraîchissement des assets","compilation des assets","développement de jeux","outils de développement","développeur Unity"],"de":["Unity-Editor","Fernbedienung","unityctl","Aktualisierung von Assets","Kompilierung von Assets","Spielentwicklung","Entwicklungstools","Unity-Entwickler"],"pt":["unityctl","controle remoto","Unity Editor","desenvolvimento de jogos","ferramentas de desenvolvimento","compilação de ativos","verificação de qualidade"],"ru":["unityctl","удаленный контроль","редактор Unity","разработка игр","инструменты разработки","компиляция активов","проверка качества"],"ar":["unityctl","التحكم عن بعد","محرر يونيتي","تطوير الألعاب","أدوات التطوير","تجميع الأصول","مراجعة الجودة"]}},"owner":"aiskillstore","repo":"marketplace","repoPath":"aiskillstore/marketplace","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.456Z","topics":[],"category":"community","skillMd":{"name":"unity-editor","description":"Remote control Unity Editor via CLI using unityctl. Use when working with Unity projects to launch/stop editor, enter/exit play mode, compile scripts, view logs, load scenes, run tests, capture screenshots, or execute C# code for debugging. Activate when user mentions Unity, play mode, compilation, or needs to interact with a running Unity Editor.","bodyPreview":"# unityctl - Unity Editor Remote Control\n\nControl a running Unity Editor from the command line without batch mode.\n\n## Instructions\n\n### Setup (Required First)\n1. Start the bridge daemon: `unityctl bridge start`\n2. Launch Unity: `unityctl editor run` or manually open the project in Unity Editor\n3. Verify connection: `unityctl status`\n\n### Refresh Assets After Script Changes\n\nAfter modifying C# scripts, refresh assets to compile:\n\n```bash\nunityctl asset refresh\n```\n\nReturns compilation errors dir","body":"# unityctl - Unity Editor Remote Control\n\nControl a running Unity Editor from the command line without batch mode.\n\n## Instructions\n\n### Setup (Required First)\n1. Start the bridge daemon: `unityctl bridge start`\n2. Launch Unity: `unityctl editor run` or manually open the project in Unity Editor\n3. Verify connection: `unityctl status`\n\n### Refresh Assets After Script Changes\n\nAfter modifying C# scripts, refresh assets to compile:\n\n```bash\nunityctl asset refresh\n```\n\nReturns compilation errors directly in the output (non-zero exit code on failure). Fix errors and re-run until compilation succeeds before entering play mode.\n\n### Common Commands\n\n**Status & Bridge:**\n```bash\nunityctl status           # Check Unity running, bridge, and connection status\nunityctl bridge start     # Start bridge daemon (runs in background)\nunityctl bridge stop      # Stop bridge\n```\n\n**Editor Lifecycle:**\n```bash\nunityctl editor run         # Launch Unity Editor (auto-detects version)\nunityctl editor stop        # Stop running Unity Editor\n```\n\n**Play Mode:**\n```bash\nunityctl play enter       # Enter play mode\nunityctl play exit        # Exit play mode\n```\n\n**Logs:**\n```bash\nunityctl logs                 # Show all logs since last clear (auto-clears on play enter and compile)\nunityctl logs -n 50           # Limit to last 50 entries\nunityctl logs --stack         # Show stack traces for log entries\nunityctl logs --full          # Show full history (ignore clear boundary)\n```\n\n**Scenes:**\n```bash\nunityctl scene list                            # List scenes\nunityctl scene load Assets/Scenes/Main.unity   # Load scene\n```\n\n**Testing:**\n```bash\nunityctl test run                    # Run edit mode tests\nunityctl test run --mode playmode    # Play mode tests\n```\n\n**Screenshots:**\n```bash\nunityctl screenshot capture          # Capture screenshot\n```\n\n### Script Execution (Debugging Power Tool)\n\nExecute arbitrary C# in the running editor via Roslyn. Invaluable for debugging and automation.\n\n```cs\n// tmp/get-version.cs\nusing UnityEngine;\n\npublic class Script\n{\n    public static object Main()\n    {\n        return Application.version;\n    }\n}\n```\n\n```bash\nunityctl script execute -f tmp/get-version.cs\n```\n\nYou can also execute code directly with `-c`:\n```bash\nunityctl script execute -c \"using UnityEngine; public class Script { public static object Main() { return Application.version; } }\"\n```\n\nScripts must define a class with a `public static object Main()` method. The return value is JSON-serialized.\n\n### Getting Help\n\n```bash\nunityctl --help              # List all commands\nunityctl <command> --help    # Command-specific help\n```\n\n## Examples\n\n**Workflow: Edit script, compile, and test:**\n```bash\n# After editing C# files...\nunityctl asset refresh       # Returns compilation errors if any\nunityctl play enter\nunityctl logs                # Check runtime logs (shows all since play enter)\nunityctl play exit\n```\n\n**Debug: Find all GameObjects in scene:**\n```cs\n// tmp/find-objects.cs\nusing UnityEngine;\n\npublic class Script\n{\n    public static object Main()\n    {\n        return GameObject.FindObjectsOfType<GameObject>().Length;\n    }\n}\n```\n```bash\nunityctl script execute -f tmp/find-objects.cs\n```\n\n**Debug: Inspect Player position:**\n```cs\n// tmp/find-player.cs\nusing UnityEngine;\n\npublic class Script\n{\n    public static object Main()\n    {\n        var go = GameObject.Find(\"Player\");\n        return go?.transform.position.ToString() ?? \"not found\";\n    }\n}\n```\n```bash\nunityctl script execute -f tmp/find-player.cs\n```\n\n**Debug: Log message to Unity console:**\n```cs\n// tmp/log-message.cs\nusing UnityEngine;\n\npublic class Script\n{\n    public static object Main()\n    {\n        Debug.Log(\"Hello from CLI\");\n        return \"logged\";\n    }\n}\n```\n```bash\nunityctl script execute -f tmp/log-message.cs\n```\n\n## Best Practices\n\n- Run `unityctl status` to check overall project status before running commands\n- Always run `unityctl asset refresh` after modifying C# files before entering play mode\n- For script execution, write scripts to `tmp/<scriptname>.cs` and execute with `-f`\n\n## Troubleshooting\n\nRun `unityctl status` first to diagnose issues.\n\n| Problem | Solution |\n|---------|----------|\n| Bridge not responding | `unityctl bridge stop` then `unityctl bridge start` |\n| Editor not connected to newly started bridge | Normal, editor plugin uses exponential backoff, up to 30 seconds |\n| Connection lost after compile | Normal - domain reload. Auto-reconnects. |\n| \"Project not found\" | Run from project directory or use `--project` flag |\n| Editor not found | Use `--unity-path` to specify Unity executable |\n"},"lastSynced":"2026-02-18T07:23:49.187Z","agentAnalysis":{"suitability":{"en":"Perfect for Game Development Agents needing Unity Editor automation and remote control capabilities.","zh":"非常适合需要Unity编辑器自动化和远程控制功能的游戏开发代理。","ja":"Unity Editorの自動化とリモート制御機能が必要なゲーム開発エージェントに最適です。","ko":"유니티 에디터 자동화 및 원격 제어 기능이 필요한 게임 개발 에이전트에게完璧합니다.","es":"Perfecto para agentes de desarrollo de juegos que necesitan automatización y control remoto del Editor de Unity.","fr":"Parfait pour les agents de développement de jeux ayant besoin d''automatisation et de contrôle à distance de l''éditeur Unity.","de":"Perfekt für Game-Development-Agents, die eine Automatisierung und Fernsteuerung des Unity-Editors benötigen.","pt":"Perfect for Game Development Agents needing Unity Editor automation and remote control capabilities.","ru":"Perfect for Game Development Agents needing Unity Editor automation and remote control capabilities.","ar":"Perfect for Game Development Agents needing Unity Editor automation and remote control capabilities."},"recommendation":{"en":"Empowers agents to control a running Unity Editor from the command line without batch mode, utilizing the unityctl bridge daemon and supporting refresh of assets after C# script changes via the unityctl asset refresh command, which returns compilation errors directory.","zh":"赋予代理从命令行控制运行中的Unity编辑器的能力，而无需批处理模式，利用unityctl桥接守护进程，并支持通过unityctl资产刷新命令刷新C#脚本更改后的资产，该命令返回编译错误目录。","ja":"エージェントがバッチモードなしでコマンドラインから実行中のUnity Editorを制御できるようにし、unityctlブリッジデーモンを利用し、unityctlアセットRefreshコマンドを介してC#スクリプトの変更後のアセットを更新し、コンパイルエラーディレクトリを返します。","ko":"에이전트가 배치 모드 없이 명령줄에서 실행 중인 유니티 에디터를 제어할 수 있도록 하며, 유니티ctl 브릿지 데몬을 사용하며, 유니티ctl 자산 새로 고침 명령을 통해 C# 스크립트 변경 후 자산을 새로 고치고 컴파일 에러 디렉토리를 반환합니다.","es":"Permite a los agentes controlar un Editor de Unity en ejecución desde la línea de comandos sin modo batch, utilizando el demonio puente unityctl y admitiendo la actualización de activos después de cambios en scripts C# a través del comando de actualización de activos unityctl, que devuelve el directorio de errores de compilación.","fr":"Permet aux agents de contrôler un éditeur Unity en cours d''exécution à partir de la ligne de commande sans mode batch, en utilisant le démon de pont unityctl et en prenant en charge la mise à jour des actifs après des modifications de script C# via la commande de rafraîchissement des actifs unityctl, qui retourne le répertoire d''erreurs de compilation.","de":"Ermöglicht es Agenten, einen laufenden Unity-Editor von der Kommandozeile aus ohne Batch-Modus zu steuern, indem es den unityctl-Brückendämon nutzt und die Aktualisierung von Assets nach Änderungen an C#-Skripten über den unityctl-Asset-Aktualisierungsbefehl unterstützt, der das Verzeichnis der Kompilierungsfehler zurückgibt.","pt":"Empowers agents to control a running Unity Editor from the command line without batch mode, utilizing the unityctl bridge daemon and supporting refresh of assets after C# script changes via the unityctl asset refresh command, which returns compilation errors directory.","ru":"Empowers agents to control a running Unity Editor from the command line without batch mode, utilizing the unityctl bridge daemon and supporting refresh of assets after C# script changes via the unityctl asset refresh command, which returns compilation errors directory.","ar":"Empowers agents to control a running Unity Editor from the command line without batch mode, utilizing the unityctl bridge daemon and supporting refresh of assets after C# script changes via the unityctl asset refresh command, which returns compilation errors directory."},"useCases":{"en":["Automating Unity Editor tasks","Refreshing assets after C# script modifications","Verifying connection status with unityctl status","Compiling assets and retrieving errors directory"],"zh":["自动化Unity编辑器任务","刷新C#脚本修改后的资产","通过unityctl状态验证连接状态","编译资产并检索错误目录"],"ja":["Unity Editorタスクの自動化","C#スクリプトの変更後のアセットの更新","unityctlステータスによる接続状態の検証","アセットのコンパイルとエラーディレクトリの取得"],"ko":["유니티 에디터 작업 자동화","C# 스크립트 수정 후 자산 새로 고침","유니티ctl 상태로 연결 상태 확인","자산 컴파일 및 에러 디렉토리 가져오기"],"es":["Automatización de tareas del Editor de Unity","Actualización de activos después de modificaciones en scripts C#","Verificación del estado de la conexión con unityctl status","Compilación de activos y recuperación del directorio de errores"],"fr":["Automatisation des tâches de l''éditeur Unity","Rafraîchissement des actifs après des modifications de script C#","Vérification de l''état de la connexion avec unityctl status","Compilation des actifs et récupération du répertoire d''erreurs"],"de":["Automatisierung von Unity-Editor-Aufgaben","Aktualisierung von Assets nach Änderungen an C#-Skripten","Überprüfung des Verbindungsstatus mit unityctl status","Kompilierung von Assets und Abruf des Verzeichnisses der Fehler"],"pt":["Automating Unity Editor tasks","Refreshing assets after C# script modifications","Verifying connection status with unityctl status","Compiling assets and retrieving errors directory"],"ru":["Automating Unity Editor tasks","Refreshing assets after C# script modifications","Verifying connection status with unityctl status","Compiling assets and retrieving errors directory"],"ar":["Automating Unity Editor tasks","Refreshing assets after C# script modifications","Verifying connection status with unityctl status","Compiling assets and retrieving errors directory"]},"limitations":{"en":["Requires Unity Editor installation","Needs bridge daemon setup with unityctl bridge start","Limited to Unity Editor remote control functionality"],"zh":["需要Unity编辑器安装","需要通过unityctl bridge start设置桥接守护进程","仅限于Unity编辑器远程控制功能"],"ja":["Unity Editorのインストールが必要","unityctlブリッジstartでブリッジデーモンをセットアップする必要がある","Unity Editorリモート制御機能に限定される"],"ko":["유니티 에디터 설치가 필요함","유니티ctl 브릿지 시작으로 브릿지 데몬을 설정해야 함","유니티 에디터 원격 제어 기능에만 제한됨"],"es":["Requiere la instalación del Editor de Unity","Necesita la configuración del demonio puente con unityctl bridge start","Limitado a la funcionalidad de control remoto del Editor de Unity"],"fr":["Nécessite l''installation de l''éditeur Unity","Nécessite la configuration du démon de pont avec unityctl bridge start","Limité à la fonctionnalité de contrôle à distance de l''éditeur Unity"],"de":["Benötigt die Installation des Unity-Editors","Benötigt die Einrichtung des Brückendämons mit unityctl bridge start","Begrenzt auf die Fernsteuerungsfunktion des Unity-Editors"],"pt":["Requires Unity Editor installation","Needs bridge daemon setup with unityctl bridge start","Limited to Unity Editor remote control functionality"],"ru":["Requires Unity Editor installation","Needs bridge daemon setup with unityctl bridge start","Limited to Unity Editor remote control functionality"],"ar":["Requires Unity Editor installation","Needs bridge daemon setup with unityctl bridge start","Limited to Unity Editor remote control functionality"]},"version":3},"qualityScore":80}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aiskillstore/marketplace/executing-plans', 'community', 'aiskillstore', 'marketplace', 'aiskillstore/marketplace', 'executing-plans', 0, 0, 65, '2026-02-18T01:08:43.456Z', '2026-02-18T07:23:56.421Z', NULL, '{"id":"aiskillstore/marketplace/executing-plans","name":"executing-plans","description":{"zh":"执行计划技能允许开发者系统化地实施计划，并在批次之间设置质量门槛。它适用于需要批次执行和人工检查点的场景","ja":"実行計画スキルは、開発者が計画をシステム化して実施し、バッチ間で品質ゲートを設定できるようにします。バッチ実行と人間のチェックポイントが必要なシナリオに適しています","ko":"실행 계획 스킬을 사용하면 개발자가 계획을 시스템화하여 구현하고 배치 간에 품질 게이트를 설정할 수 있습니다. 배치 실행 및 인간의 확인 점이 필요한 시나리오에 적합합니다","es":"El skill de ejecución de planes permite implementar planes de manera sistemática con calidad y eficiencia, con controles humanos y verificación de calidad","fr":"Le skill d''exécution de plans permet de mettre en œuvre des plans de manière systématique avec qualité et efficacité, avec des contrôles humains et une vérification de qualité","de":"Das Skill zur Ausführung von Plänen ermöglicht die systematische Ausführung von Implementierungsplänen mit Qualität und Effizienz, mit menschlichen Kontrollen und Qualitätsüberprüfung","pt":"Executando planos de implementação de forma sistemática com qualidade verificada.","ru":"Выполнение планов реализации в систематичном порядке с проверкой качества.","ar":"تنفيذ الخطط الإجرائية بشكل منهجي مع جودة موثوقة.","en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"seo":{"title":{"zh":"执行计划技能 - 系统化实施与质量控制","ja":"実行計画スキル - システム化された実施と品質管理","ko":"실행 계획 스킬 - 시스템화된 구현 및 품질 제어","es":"Ejecutar planes de implementación de manera sistemática","fr":"Exécuter des plans d''implémentation de manière systématique","de":"Systematische Ausführung von Implementierungsplänen","pt":"Executando Planos de Implementação","ru":"Выполнение Планов Реализации","ar":"تنفيذ الخطط الإجرائية","en":"executing-plans"},"description":{"zh":"执行计划技能允许开发者系统化地实施计划，并在批次之间设置质量门槛。它适用于需要批次执行和人工检查点的场景","ja":"実行計画スキルは、開発者が計画をシステム化して実施し、バッチ間で品質ゲートを設定できるようにします。バッチ実行と人間のチェックポイントが必要なシナリオに適しています","ko":"실행 계획 스킬을 사용하면 개발자가 계획을 시스템화하여 구현하고 배치 간에 품질 게이트를 설정할 수 있습니다. 배치 실행 및 인간의 확인 점이 필요한 시나리오에 적합합니다","es":"El skill de ejecución de planes permite implementar planes de manera sistemática con calidad y eficiencia, con controles humanos y verificación de calidad","fr":"Le skill d''exécution de plans permet de mettre en œuvre des plans de manière systématique avec qualité et efficacité, avec des contrôles humains et une vérif...","de":"Das Skill zur Ausführung von Plänen ermöglicht die systematische Ausführung von Implementierungsplänen mit Qualität und Effizienz, mit menschlichen Kontrolle...","pt":"Executando planos de implementação de forma sistemática com qualidade verificada.","ru":"Выполнение планов реализации в систематичном порядке с проверкой качества.","ar":"تنفيذ الخطط الإجرائية بشكل منهجي مع جودة موثوقة.","en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"definition":{"en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"features":{"zh":["系统化实施计划","批次之间设置质量门槛","支持 Claude、Codex 和 Claude Code","一键安装和质量验证","批次执行和人工检查点"],"ja":["計画をシステム化して実施","バッチ間で品質ゲートを設定","Claude、Codex、Claude Code に対応","ワンクリックインストールと品質検証","バッチ実行と人間のチェックポイント"],"ko":["계획을 시스템화하여 구현","배치 간에 품질 게이트를 설정","Claude, Codex, Claude Code에 적합","원클릭 설치 및 품질 검증","배치 실행 및 인간의 확인 점"],"es":["Carga y revisión de planes","Identificación de posibles problemas o ambigüedades","Creación de tareas con TodoWrite","Ejecución por lotes con controles humanos","Verificación de calidad"],"fr":["Chargement et révision de plans","Identification de problèmes ou d''ambiguïtés potentiels","Création de tâches avec TodoWrite","Exécution par lots avec des contrôles humains","Vérification de qualité"],"de":["Laden und Überprüfen von Plänen","Identifizierung von möglichen Problemen oder Unklarheiten","Erstellung von Aufgaben mit TodoWrite","Ausführung in Batches mit menschlichen Kontrollen","Qualitätsüberprüfung"],"pt":["Execução sistemática de planos","Portas de qualidade entre lotes","Revisão e identificação de problemas potenciais","Criação de TodoWrite com todas as tarefas","Execução em lotes com pontos de verificação humanos"],"ru":["Систематическое выполнение планов","Качественные ворота между партиями","Просмотр и выявление потенциальных проблем","Создание TodoWrite со всеми задачами","Выполнение в партиях с человеческими контрольными точками"],"ar":["تنفيذ الخطط الإجرائية بشكل منهجي","بوابات جودة بين الدفعات","مراجعة وتحديد المشكلات المحتملة","إنشاء TodoWrite مع جميع المهام","تنفيذ الدفعات مع نقاط فحص بشرية"]},"keywords":{"zh":["执行计划技能","系统化实施","质量控制","Claude","Codex","Claude Code","批次执行","人工检查点"],"ja":["実行計画スキル","システム化された実施","品質管理","Claude","Codex","Claude Code","バッチ実行","人間のチェックポイント"],"ko":["실행 계획 스킬","시스템화된 구현","품질 제어","Claude","Codex","Claude Code","배치 실행","인간의 확인 점"],"es":["ejecución de planes","implementación de planes","calidad y eficiencia","controles humanos","verificación de calidad","desarrollo de software"],"fr":["exécution de plans","mise en œuvre de plans","qualité et efficacité","contrôles humains","vérification de qualité","développement de logiciels"],"de":["Ausführung von Plänen","Umsetzung von Plänen","Qualität und Effizienz","menschliche Kontrollen","Qualitätsüberprüfung","Software-Entwicklung"],"pt":["executando planos","implementação de planos","qualidade verificada","portas de qualidade","revisão de planos","todoWrite","execução em lotes"],"ru":["выполнение планов","реализация планов","проверка качества","качественные ворота","просмотр планов","todoWrite","выполнение в партиях"],"ar":["تنفيذ الخطط","تنفيذ الخطط الإجرائية","جودة موثوقة","بوابات جودة","مراجعة الخطط","todoWrite","تنفيذ الدفعات"]}},"owner":"aiskillstore","repo":"marketplace","repoPath":"aiskillstore/marketplace","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.456Z","topics":[],"category":"community","skillMd":{"name":"executing-plans","description":"Execute implementation plans with batch processing and review checkpoints. Use when given a plan document.","bodyPreview":"# Executing Plans\n\nExecute implementation plans systematically with quality gates between batches.\n\n## When to Use\n\n- When given a plan document to implement\n- After writing-plans skill produces a plan\n- For batch execution with human checkpoints\n\n## The Five-Step Process\n\n### Step 1: Load and Review Plan\n\n1. Read the plan document carefully\n2. Identify potential issues or ambiguities\n3. Raise concerns with user **before** beginning work\n4. Create TodoWrite with all tasks if plan seems sound\n\n**","body":"# Executing Plans\n\nExecute implementation plans systematically with quality gates between batches.\n\n## When to Use\n\n- When given a plan document to implement\n- After writing-plans skill produces a plan\n- For batch execution with human checkpoints\n\n## The Five-Step Process\n\n### Step 1: Load and Review Plan\n\n1. Read the plan document carefully\n2. Identify potential issues or ambiguities\n3. Raise concerns with user **before** beginning work\n4. Create TodoWrite with all tasks if plan seems sound\n\n**If issues found:** Stop and clarify before proceeding\n\n### Step 2: Execute Batch\n\nDefault batch size: **3 tasks**\n\nFor each task in batch:\n\n1. Update status to `in_progress`\n2. Execute each step as written\n3. Run specified verifications\n4. Mark as `completed` only when verified\n\n### Step 3: Report\n\nAfter completing a batch:\n\n```markdown\n## Batch Complete\n\n**Tasks Completed:** [List]\n\n**Verifications:**\n\n- Task 1: [Pass/Fail] - [Details]\n- Task 2: [Pass/Fail] - [Details]\n- Task 3: [Pass/Fail] - [Details]\n\n**Issues Found:** [If any]\n\nReady for feedback.\n```\n\n### Step 4: Continue\n\n1. Incorporate any requested changes\n2. Execute next batch\n3. Repeat cycle\n\n### Step 5: Complete Development\n\nAfter all tasks finished and verified:\n\n1. Run full test suite\n2. Announce completion\n3. Transition to finishing workflow (merge/PR decision)\n\n## Critical Rules\n\n### STOP Immediately When:\n\n- Blockers (missing dependencies, failed tests)\n- Plan gaps preventing progress\n- Unclear instructions\n- Repeated verification failures (2+ on same task)\n\n**When blocked:** Ask for clarification, don''t force through.\n\n### Return to Step 1 When:\n\n- User updates the plan\n- Approach needs fundamental revision\n- Architecture issues discovered\n\n### Never:\n\n- Skip verifications\n- Force through blockers\n- Batch completions (mark done one at a time)\n- Proceed with unresolved critical issues\n\n## Batch Size Guidelines\n\n| Scenario          | Batch Size   |\n| ----------------- | ------------ |\n| Simple tasks      | 3-5          |\n| Complex tasks     | 1-2          |\n| High-risk changes | 1            |\n| User preference   | As specified |\n\n## Integration with Other Skills\n\n- **test-driven-development:** Each task follows TDD\n- **systematic-debugging:** If tests fail, use debugging skill\n- **code-review:** Request review after significant batches\n"},"lastSynced":"2026-02-18T07:23:56.421Z","agentAnalysis":{"suitability":{"en":"Ideal for Project Management Agents requiring systematic plan execution with quality gates and human checkpoints.","zh":"适合需要系统计划执行、质量门控和人工检查点的项目管理代理","ja":"プロジェクト管理エージェントが体系的な計画実行と品質ゲート、人間によるチェックポイントを必要とする場合に適しています","ko":"시스템적인 계획 실행과 품질 게이트 및 인간 체크포인트가 필요한 프로젝트 관리 에이전트에 적합합니다","es":"Ideal para agentes de gestión de proyectos que requieren una ejecución de planes sistemática con puertas de calidad y puntos de control humanos.","fr":"Idéal pour les agents de gestion de projet nécessitant une exécution de plans systématique avec des portes de qualité et des points de contrôle humains.","de":"Ideal für Projektmanagement-Agenten, die eine systematische Planumsetzung mit Qualitätsprüfungen und menschlichen Prüfpunkten erfordern.","pt":"Ideal para Agentes de Gerenciamento de Projetos que requerem execução sistemática de planos com portas de qualidade e pontos de verificação humanos.","ru":"Идеально подходит для агентов по управлению проектами, требующих системного выполнения планов с контролем качества и человеческими контрольными точками.","ar":"مثالي لعميل إدارة المشاريع الذي يتطلب تنفيذًا منهجيًا للخطط مع بوابات جودة ومراجعة بشرية"},"recommendation":{"en":"Empowers agents to execute implementation plans systematically, utilizing quality gates between batches and TodoWrite for task management, ensuring seamless plan execution with human oversight through protocols like batch execution and checkpoint reviews.","zh":"赋予代理执行实施计划的能力，系统地利用批次之间的质量门控和TodoWrite进行任务管理，通过批次执行和检查点审查等协议，确保计划执行的无缝进行和人类的监督","ja":"エージェントに実施計画を体系的に実行する能力を付与し、バッチ間の品質ゲートとTodoWriteを使用してタスク管理を行い、バッチ実行とチェックポイントレビューなどのプロトコルを通じて、計画の実行を無邪気に行い、人間による監視を確実に行う","ko":"에이전트가 실행 계획을 체계적으로 실행할 수 있는 능력을 부여하고, 배치 간의 품질 게이트와 TodoWrite를 사용하여 태스크 관리를 수행하며, 배치 실행 및 체크포인트 리뷰 등의 프로토콜을 통해 계획 실행의 무결성을 보장하고 인간의 감시를 통해 확인합니다","es":"Habilita a los agentes a ejecutar planes de implementación de manera sistemática, utilizando puertas de calidad entre lotes y TodoWrite para la gestión de tareas, asegurando una ejecución de planes sin problemas con supervisión humana a través de protocolos como la ejecución de lotes y la revisión de puntos de control.","fr":"Permet aux agents d''exécuter des plans de mise en œuvre de manière systématique, en utilisant des portes de qualité entre les lots et TodoWrite pour la gestion des tâches, en garantissant une exécution de plans sans heurts avec une surveillance humaine via des protocoles tels que l''exécution de lots et l''examen des points de contrôle.","de":"Ermächtigt Agenten, Umsetzungspläne systematisch auszuführen, indem Qualitätsprüfungen zwischen Chargen und TodoWrite für die Aufgabenverwaltung verwendet werden, um eine reibungslose Planumsetzung mit menschlicher Überwachung durch Protokolle wie Chargenausführung und Prüfpunkte-Überprüfung sicherzustellen.","pt":"Habilita os agentes a executar planos de implementação sistematicamente, utilizando portas de qualidade entre lotes e TodoWrite para gerenciamento de tarefas, garantindo execução de plano sem interrupções com supervisão humana por meio de protocolos como execução de lote e revisões de pontos de verificação.","ru":"Наделяет агентов возможностью выполнять планы реализации системно, используя контролем качества между партиями и TodoWrite для управления задачами, обеспечивая бесперебойное выполнение планов с человеческим надзором посредством протоколов, таких как выполнение партии и проверка контрольных точек.","ar":"يمنح الوكيل khảية تنفيذ خطط التنفيذ بشكل منهجي، باستخدام بوابات جودة بين الدفعات و TodoWrite لإدارة المهام، مما يضمن تنفيذ الخطة دون انقطاع مع الإشراف البشري من خلال بروتوكولات مثل تنفيذ الدفعة ومراجعة نقاط الفحص"},"useCases":{"en":["Executing project plans with multiple stakeholders","Implementing batch processing with quality control checkpoints","Systematically reviewing and addressing potential issues in plan documents"],"zh":["执行涉及多个利益相关者的项目计划","实施带有质量控制检查点的批处理","系统地审查和解决计划文档中的潜在问题"],"ja":["複数のステークホルダーを含むプロジェクト計画の実行","品質管理チェックポイントを含むバッチ処理の実施","計画文書の中の潜在的な問題を体系的に確認し、対応する"],"ko":["여러 이해관계자가 포함된 프로젝트 계획의 실행","품질 관리 체크포인트를 포함한 배치 처리의 구현","계획 문서에서의 잠재적인 문제를 체계적으로 검토하고 해결한다"],"es":["Ejecutar planes de proyecto con múltiples partes interesadas","Implementar el procesamiento por lotes con puntos de control de control de calidad","Revisar y abordar sistemáticamente posibles problemas en los documentos del plan"],"fr":["Exécuter des plans de projet avec plusieurs parties prenantes","Mettre en œuvre le traitement par lots avec des points de contrôle de contrôle de qualité","Examiner et traiter systématiquement les problèmes potentiels dans les documents de plan"],"de":["Projektpläne mit mehreren Beteiligten auszuführen","Chargeverarbeitung mit Qualitätskontrollprüfpunkten umzusetzen","Mögliche Probleme in Planunterlagen systematisch zu überprüfen und anzugehen"],"pt":["Executar planos de projeto com vários stakeholders","Implementar processamento em lote com pontos de verificação de controle de qualidade","Revisar e abordar sistematicamente problemas potenciais em documentos de plano"],"ru":["Выполнять планы проекта с несколькими заинтересованными сторонами","Реализовывать пакетную обработку с контрольными точками контроля качества","Систематически просматривать и устранять потенциальные проблемы в документах плана"],"ar":["تنفيذ خطط المشروع مع أصحاب المصلحة المتعددين","تنفيذ المعالجة الدفعية مع نقاط فحص لمراقبة الجودة","مراجعة ومناقشة منهجية للمشاكل المحتملة في وثائق الخطة"]},"limitations":{"en":["Requires a plan document to implement","Dependent on human input for concern resolution and checkpoint approvals"],"zh":["需要计划文档来实施","依赖于人类的输入来解决问题和检查点批准"],"ja":["実施するには計画文書が必要","問題解決とチェックポイントの承認には人間の入力に依存する"],"ko":["구현하기 위해서는 계획 문서가 필요합니다","문제 해결 및 체크포인트 승인에는 인간의 입력에 의존합니다"],"es":["Requiere un documento de plan para implementar","Depende de la entrada humana para la resolución de inquietudes y la aprobación de puntos de control"],"fr":["Nécessite un document de plan pour la mise en œuvre","Dépend de l''entrée humaine pour la résolution des préoccupations et l''approbation des points de contrôle"],"de":["Benötigt ein Plan-Dokument zur Umsetzung","Hängt von der menschlichen Eingabe für die Lösung von Bedenken und die Genehmigung von Prüfpunkten ab"],"pt":["Requer um documento de plano para implementação","Depende da entrada humana para resolução de preocupações e aprovações de pontos de verificação"],"ru":["Требует документа плана для реализации","Зависит от человеческого ввода для решения проблем и утверждения контрольных точек"],"ar":["يتطلب وثيقة خطة للتنفيذ","يعتمد على المدخلات البشرية لحل القلق والموافقة على نقاط الفحص"]},"version":3},"qualityScore":65}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aiskillstore/marketplace/react-performance', 'community', 'aiskillstore', 'marketplace', 'aiskillstore/marketplace', 'react-performance', 0, 0, 45, '2026-02-18T01:08:43.456Z', '2026-02-18T07:24:03.031Z', NULL, '{"id":"aiskillstore/marketplace/react-performance","name":"react-performance","description":{"zh":"React性能优化是通过理解React的渲染行为来解决不必要的重新渲染、未优化的列表和昂贵的计算问题","ja":"Reactパフォーマンス最適化は、Reactの描画動作を理解することで不要な再描画、未最適化のリスト、コストのかかる計算の問題を解決する","ko":"리액트 성능 최적화는 리액트의 렌더링 행동을 이해함으로써 불필요한 재렌더링, 최적화되지 않은 목록 및 비싼 계산 문제를 해결하는 것을 의미합니다","es":"Mejora el rendimiento de tus aplicaciones React con técnicas de memoización y optimización de listas","fr":"Améliorez les performances de vos applications React avec des techniques de mémoïsation et d''optimisation des listes","de":"Verbessern Sie die Leistung Ihrer React-Anwendungen mit Memoisierungstechniken und Listoptimierung","pt":"Otimizar o desempenho do React é fundamental para construir aplicações web rápidas e eficientes. Aprenda a evitar re-renderizações desnecessárias e a otimizar listas e cálculos","ru":"Оптимизация производительности React является фундаментальной для построения быстрых и эффективных веб-приложений. Узнайте, как избежать ненужных перерисовок и оптимизировать списки и вычисления","ar":"تحسين أداء رياكت هو أمر أساسي لإنشاء تطبيقات ويب سريعة وفعالة. تعلم كيفية تجنب إعادة التصيير غير الضرورية وتحسين القوائم والحسابات","en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"seo":{"title":{"zh":"React性能优化","ja":"Reactパフォーマンス最適化","ko":"리액트 성능 최적화","es":"Optimiza el rendimiento de React","fr":"Améliorez les performances de React","de":"React-Performance optimieren","pt":"Otimização de Desempenho do React","ru":"Оптимизация производительности React","ar":"تحسين أداء رياكت","en":"react-performance"},"description":{"zh