INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('oimiragieo/agent-studio/windows-compatibility', 'community', 'oimiragieo', 'agent-studio', 'oimiragieo/agent-studio', 'windows-compatibility', 0, 0, 35, '2026-02-18T01:08:43.460Z', '2026-02-18T07:47:51.958Z', NULL, '{"id":"oimiragieo/agent-studio/windows-compatibility","name":"windows-compatibility","description":{"zh":"Windows兼容性技能是指编写可以在Windows系统上运行Git Bash的跨平台代码的能力","ja":"Windows互換性スキルとは、Windowsシステム上でGit Bashを実行できるクロスプラットフォームコードを書く能力です","ko":"윈도우 호환성 스킬은 윈도우 시스템에서 Git Bash를 실행할 수 있는 크로스 플랫폼 코드를 작성하는 능력을 의미합니다","es":"El skill de compatibilidad con Windows permite a los desarrolladores escribir código que se ejecuta correctamente en sistemas Windows con Git Bash.","fr":"Le skill de compatibilité Windows permet aux développeurs d''écrire du code qui s''exécute correctement sur les systèmes Windows avec Git Bash.","de":"Das Windows-Kompatibilitäts-Skill ermöglicht es Entwicklern, Code zu schreiben, der korrekt auf Windows-Systemen mit Git Bash ausgeführt wird.","pt":"O skill de compatibilidade com Windows permite que desenvolvedores escrevam código cross-plataforma que funciona corretamente em sistemas Windows com Git Bash.","ru":"Навык совместимости с Windows позволяет разработчикам писать кроссплатформенный код, который работает правильно в системах Windows с Git Bash.","ar":"مهارة توافق نظام التشغيل Windows تمكن المطورين من كتابة كود متوافق مع الأنظمة العابرة التي تعمل بشكل صحيح على أنظمة Windows مع Git Bash.","en":""},"seo":{"title":{"zh":"Windows兼容性技能","ja":"Windows互換性スキル","ko":"윈도우 호환성 스킬","es":"Compatibilidad con Windows para desarrolladores","fr":"Compatibilité Windows pour les développeurs","de":"Windows-Kompatibilität für Entwickler","pt":"Compatibilidade com Windows: Desenvolvimento Cross-Plataf...","ru":"Совместимость с Windows: Кроссплатформенное Разработка","ar":"توافق نظام التشغيل WINDOWS: التطوير العابر للأنظمة","en":"windows-compatibility"},"description":{"zh":"Windows兼容性技能是指编写可以在Windows系统上运行Git Bash的跨平台代码的能力","ja":"Windows互換性スキルとは、Windowsシステム上でGit Bashを実行できるクロスプラットフォームコードを書く能力です","ko":"윈도우 호환성 스킬은 윈도우 시스템에서 Git Bash를 실행할 수 있는 크로스 플랫폼 코드를 작성하는 능력을 의미합니다","es":"El skill de compatibilidad con Windows permite a los desarrolladores escribir código que se ejecuta correctamente en sistemas Windows con Git Bash.","fr":"Le skill de compatibilité Windows permet aux développeurs d''écrire du code qui s''exécute correctement sur les systèmes Windows avec Git Bash.","de":"Das Windows-Kompatibilitäts-Skill ermöglicht es Entwicklern, Code zu schreiben, der korrekt auf Windows-Systemen mit Git Bash ausgeführt wird.","pt":"O skill de compatibilidade com Windows permite que desenvolvedores escrevam código cross-plataforma que funciona corretamente em sistemas Windows com Git Bash.","ru":"Навык совместимости с Windows позволяет разработчикам писать кроссплатформенный код, который работает правильно в системах Windows с Git Bash.","ar":"مهارة توافق نظام التشغيل Windows تمكن المطورين من كتابة كود متوافق مع الأنظمة العابرة التي تعمل بشكل صحيح على أنظمة Windows مع Git Bash.","en":""},"definition":{"en":""},"features":{"zh":["使用bash/POSIX语法","避免使用Windows CMD语法","避免使用PowerShell语法","支持Git Bash命令","跨平台代码兼容性"],"ja":["bash/POSIX構文を使用","Windows CMD構文を避ける","PowerShell構文を避ける","Git Bashコマンドをサポート","クロスプラットフォームコードの互換性"],"ko":["bash/POSIX 구문을 사용","윈도우 CMD 구문을 피함","PowerShell 구문을 피함","Git Bash 명령어 지원","크로스 플랫폼 코드 호환성"],"es":["Uso de sintaxis bash/POSIX","Compatibilidad con Git Bash","Evitación de la sintaxis de Windows CMD","Evitación de la sintaxis de PowerShell","Escritura de código cross-platform","Ejecución correcta en sistemas Windows"],"fr":["Utilisation de la syntaxe bash/POSIX","Compatibilité avec Git Bash","Évitement de la syntaxe Windows CMD","Évitement de la syntaxe PowerShell","Écriture de code cross-platform","Exécution correcte sur les systèmes Windows"],"de":["Verwendung von bash/POSIX-Syntax","Kompatibilität mit Git Bash","Vermeidung von Windows-CMD-Syntax","Vermeidung von PowerShell-Syntax","Schreiben von cross-platform-Code","Korrekte Ausführung auf Windows-Systemen"],"pt":["Uso de sintaxe bash/POSIX para comandos de shell","Compatibilidade com sistemas Windows com Git Bash","Evite a sintaxe do Windows CMD e do PowerShell","Desenvolvimento cross-plataforma","Uso de comandos Git Bash (/usr/bin/bash)"],"ru":["Использование синтаксиса bash/POSIX для команд shell","Совместимость с системами Windows с Git Bash","Избегайте синтаксиса Windows CMD и PowerShell","Кроссплатформенная разработка","Использование команд Git Bash (/usr/bin/bash)"],"ar":["استخدام بنية باش/بوزيكس لاوامر شل","التوافق مع أنظمة Windows مع Git Bash","تجنب بنية نظام التشغيل Windows CMD وباور شيل","التطوير العابر للأنظمة","استخدام أوامر Git Bash (/usr/bin/bash)"]},"keywords":{"zh":["Windows兼容性","跨平台代码","Git Bash","bash/POSIX语法","Windows CMD","PowerShell","代码兼容性"],"ja":["Windows互換性","クロスプラットフォームコード","Git Bash","bash/POSIX構文","Windows CMD","PowerShell","コードの互換性"],"ko":["윈도우 호환성","크로스 플랫폼 코드","Git Bash","bash/POSIX 구문","윈도우 CMD","PowerShell","코드 호환성"],"es":["compatibilidad con Windows","código cross-platform","Git Bash","sintaxis bash/POSIX","desarrollo de software","sistemas operativos Windows","compatibilidad de código","entornos de desarrollo"],"fr":["compatibilité Windows","code cross-platform","Git Bash","syntaxe bash/POSIX","développement de logiciels","systèmes d''exploitation Windows","compatibilité de code","environnements de développement"],"de":["Windows-Kompatibilität","cross-platform-Code","Git Bash","bash/POSIX-Syntax","Software-Entwicklung","Windows-Betriebssysteme","Code-Kompatibilität","Entwicklungsumgebungen"],"pt":["compatibilidade com windows","desenvolvimento cross-plataforma","git bash","bash/posix","sintaxe de shell","desenvolvedores","código compatível"],"ru":["совместимость с windows","кроссплатформенная разработка","git bash","bash/posix","синтаксис shell","разработчики","совместимый код"],"ar":["توافق نظام التشغيل windows","التطوير العابر للأنظمة","جيت باش","باش/بوزيكس","بنية شل","مطورين","كود متوافق"]}},"owner":"oimiragieo","repo":"agent-studio","repoPath":"oimiragieo/agent-studio","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.460Z","topics":[],"category":"community","skillMd":{"name":"windows-compatibility","description":"Guidelines for working on Windows with Git Bash. Use bash/POSIX syntax for shell commands, not CMD or PowerShell syntax, since the Bash tool runs through Git Bash.","version":"2.0.0","bodyPreview":"# Windows Compatibility Skill\n\n<identity>\nYou are an expert at writing cross-platform code that works correctly on Windows systems running Git Bash.\n</identity>\n\n## Critical Rule: Bash Tool Uses Git Bash\n\n**The Bash tool runs commands through Git Bash (`/usr/bin/bash`), NOT Windows CMD or PowerShell.**\n\nThis means:\n\n- Use **bash/POSIX syntax** for all shell commands\n- Do NOT use Windows CMD syntax (`if not exist`, `copy`, `del`)\n- Do NOT use PowerShell syntax (`Remove-Item`, `New-Item`)\n\n## Comm","body":"# Windows Compatibility Skill\n\n<identity>\nYou are an expert at writing cross-platform code that works correctly on Windows systems running Git Bash.\n</identity>\n\n## Critical Rule: Bash Tool Uses Git Bash\n\n**The Bash tool runs commands through Git Bash (`/usr/bin/bash`), NOT Windows CMD or PowerShell.**\n\nThis means:\n\n- Use **bash/POSIX syntax** for all shell commands\n- Do NOT use Windows CMD syntax (`if not exist`, `copy`, `del`)\n- Do NOT use PowerShell syntax (`Remove-Item`, `New-Item`)\n\n## Command Syntax Reference\n\n### Directory Operations\n\n| Task             | ✅ Correct (Bash)      | ❌ Wrong (CMD)      | ❌ Wrong (PowerShell)          |\n| ---------------- | ---------------------- | ------------------- | ------------------------------ |\n| Create directory | `mkdir -p path/to/dir` | `mkdir path\\to\\dir` | `New-Item -ItemType Directory` |\n| Check if exists  | `[ -d \"path\" ] && ...` | `if exist path ...` | `Test-Path path`               |\n| Remove directory | `rm -rf path/to/dir`   | `rmdir /s /q path`  | `Remove-Item -Recurse`         |\n| List files       | `ls -la`               | `dir`               | `Get-ChildItem`                |\n\n### File Operations\n\n| Task              | ✅ Correct (Bash)                        | ❌ Wrong (CMD)     | ❌ Wrong (PowerShell) |\n| ----------------- | ---------------------------------------- | ------------------ | --------------------- |\n| Create empty file | `touch file.txt` or `echo \"\" > file.txt` | `echo. > file.txt` | `New-Item file.txt`   |\n| Copy file         | `cp src dest`                            | `copy src dest`    | `Copy-Item`           |\n| Move file         | `mv src dest`                            | `move src dest`    | `Move-Item`           |\n| Delete file       | `rm file.txt`                            | `del file.txt`     | `Remove-Item`         |\n| Read file         | `cat file.txt`                           | `type file.txt`    | `Get-Content`         |\n\n### Conditional Operations\n\n| Task                   | ✅ Correct (Bash)                | ❌ Wrong (CMD)               |\n| ---------------------- | -------------------------------- | ---------------------------- |\n| If directory exists    | `[ -d \"path\" ] && echo \"exists\"` | `if exist path\\ echo exists` |\n| If file exists         | `[ -f \"file\" ] && echo \"exists\"` | `if exist file echo exists`  |\n| Multi-line conditional | `if [ condition ]; then ... fi`  | `if condition ( ... )`       |\n\n### Path Handling\n\n- Use **forward slashes** in bash: `.claude/context/memory/`\n- Git Bash auto-converts Windows paths, but prefer forward slashes\n- Quote paths with spaces: `\"path with spaces/file.txt\"`\n\n## Common Mistakes to Avoid\n\n### ❌ Windows CMD Multi-line If\n\n```batch\n# WRONG - Git Bash cannot parse this\nif not exist \"path\" mkdir \"path\"\nif not exist \"other\" mkdir \"other\"\n```\n\n### ✅ Bash Equivalent\n\n```bash\n# CORRECT - Use bash syntax\nmkdir -p path other\n# Or with explicit check:\n[ -d \"path\" ] || mkdir -p path\n```\n\n### ❌ Touch Command Failure Handling\n\n```bash\n# WRONG - touch may not exist on Windows, fails silently\ntouch file.txt 2>/dev/null\n```\n\n### ✅ Portable Alternative\n\n```bash\n# CORRECT - echo works everywhere in bash\necho \"\" > file.txt\n# Or use mkdir -p for directories (never fails if exists)\nmkdir -p path/to/dir\n```\n\n## Node.js Cross-Platform Tips\n\nWhen writing JavaScript/Node.js code:\n\n```javascript\n// Use path.join() for cross-platform paths\nconst filePath = path.join(__dirname, ''subdir'', ''file.txt'');\n\n// Use fs.mkdir with recursive option\nfs.mkdirSync(dirPath, { recursive: true });\n\n// Check platform if needed\nif (process.platform === ''win32'') {\n  // Windows-specific handling\n}\n```\n\n## Memory Protocol (MANDATORY)\n\n**Before starting:**\n\n```bash\ncat .claude/context/memory/learnings.md\n```\n\n**After completing:** Record any new patterns or exceptions discovered.\n\n> ASSUME INTERRUPTION: Your context may reset. If it''s not in memory, it didn''t happen.\n"},"lastSynced":"2026-02-18T07:47:51.958Z","agentAnalysis":{"suitability":{"en":"Perfect for Cross-Platform Agents requiring seamless Git Bash integration on Windows systems","zh":"适用于需要在Windows系统上实现无缝Git Bash集成的跨平台代理","ja":"Windowsシステム上でのシームレスなGit Bash統合を必要とするクロスプラットフォームエージェントに適しています","ko":"윈도우 시스템에서 무중단 Git Bash 통합을 필요한 크로스 플랫폼 에이전트에 적합합니다","es":"Perfecto para agentes de plataforma cruzada que requieren una integración perfecta de Git Bash en sistemas Windows","fr":"Parfait pour les agents de plateforme croisée nécessitant une intégration transparente de Git Bash sur les systèmes Windows","de":"Perfekt für Cross-Platform-Agents, die eine nahtlose Git-Bash-Integration in Windows-Systemen erfordern","pt":"Perfeito para Agentes Cross-Platform que requerem integração sem interrupções do Git Bash em sistemas Windows","ru":"Идеально для агентов с поддержкой нескольких платформ, требующих бесшовной интеграции Git Bash в системах Windows","ar":"مثالي لعميل متوافق مع منصات متعددة يتطلب تكامل Git Bash بدون انقطاع في أنظمة Windows"},"recommendation":{"en":"Empowers agents to execute bash/POSIX syntax commands through Git Bash, ensuring compatibility with Windows systems and enabling the use of bash tools like /usr/bin/bash, while avoiding Windows CMD and PowerShell syntax","zh":"赋予代理执行bash/POSIX语法命令的能力，通过Git Bash确保与Windows系统的兼容性，并启用使用bash工具，如/usr/bin/bash，同时避免使用Windows CMD和PowerShell语法","ja":"エージェントにbash/POSIX構文のコマンドを実行する能力を付与し、Git Bashを介してWindowsシステムとの互換性を確保し、bashツール（例：/usr/bin/bash）を使用できるようにし、同時にWindows CMDおよびPowerShell構文の使用を避ける","ko":"에이전트가 Git Bash를 통해 bash/POSIX 구문 명령을 실행할 수 있는 능력을 부여하여 윈도우 시스템과의 호환성을 보장하고 bash 도구(/usr/bin/bash 등)를 사용할 수 있도록 하며,同時에 윈도우 CMD 및 PowerShell 구문을 피함","es":"Habilita a los agentes a ejecutar comandos de sintaxis bash/POSIX a través de Git Bash, garantizando la compatibilidad con los sistemas Windows y permitiendo el uso de herramientas bash como /usr/bin/bash, evitando la sintaxis de Windows CMD y PowerShell","fr":"Permet aux agents d''exécuter des commandes de syntaxe bash/POSIX via Git Bash, garantissant la compatibilité avec les systèmes Windows et permettant l''utilisation d''outils bash tels que /usr/bin/bash, tout en évitant la syntaxe de Windows CMD et PowerShell","de":"Ermächtigt die Agenten, bash/POSIX-Syntax-Befehle über Git Bash auszuführen, wodurch die Kompatibilität mit Windows-Systemen sichergestellt und die Verwendung von bash-Tools wie /usr/bin/bash ermöglicht wird, während die Syntax von Windows CMD und PowerShell vermieden wird","pt":"Habilita os agentes a executar comandos de sintaxe bash/POSIX por meio do Git Bash, garantindo a compatibilidade com sistemas Windows e permitindo o uso de ferramentas bash como /usr/bin/bash, enquanto evita a sintaxe do Windows CMD e PowerShell","ru":"Наделяет агентов возможностью выполнять команды синтаксиса bash/POSIX через Git Bash, обеспечивая совместимость с системами Windows и позволяя использовать инструменты bash, такие как /usr/bin/bash, а также избегая синтаксиса Windows CMD и PowerShell","ar":"تمكّن الوكيل من تشغيل أوامر بناء جملة bash/POSIX من خلال Git Bash، مما يضمن التوافق مع أنظمة Windows ويمكّن استخدام أدوات bash مثل /usr/bin/bash، مع تجنب بناء جملة Windows CMD و PowerShell"},"useCases":{"en":["Executing bash scripts on Windows","Utilizing Git Bash for version control","Running POSIX-compliant commands on Windows systems"],"zh":["在Windows上执行bash脚本","利用Git Bash进行版本控制","在Windows系统上运行POSIX兼容命令"],"ja":["Windows上でbashスクリプトを実行する","Git Bashを使用したバージョン管理","Windowsシステム上でPOSIX準拠コマンドを実行する"],"ko":["윈도우에서 bash 스크립트 실행","Git Bash를 사용한 버전 관리","윈도우 시스템에서 POSIX 호환 명령어 실행"],"es":["Ejecutar scripts de bash en Windows","Utilizar Git Bash para el control de versiones","Ejecutar comandos compatibles con POSIX en sistemas Windows"],"fr":["Exécuter des scripts bash sur Windows","Utiliser Git Bash pour le contrôle de version","Exécuter des commandes compatibles POSIX sur les systèmes Windows"],"de":["Bash-Skripte auf Windows ausführen","Git Bash für die Versionskontrolle verwenden","POSIX-kompatible Befehle auf Windows-Systemen ausführen"],"pt":["Executar scripts bash no Windows","Utilizar Git Bash para controle de versão","Executar comandos compatíveis com POSIX em sistemas Windows"],"ru":["Выполнять скрипты bash в Windows","Использовать Git Bash для контроля версий","Выполнять команды, совместимые с POSIX, в системах Windows"],"ar":["تشغيل سكريبتات bash على Windows","استخدام Git Bash للتحكم في الإصدارات","تشغيل أوامر متوافقة مع POSIX على أنظمة Windows"]},"limitations":{"en":["Requires Git Bash installation on Windows","Limited to bash/POSIX syntax","Incompatible with Windows CMD and PowerShell syntax"],"zh":["需要在Windows上安装Git Bash","仅限bash/POSIX语法","与Windows CMD和PowerShell语法不兼容"],"ja":["Windows上でGit Bashをインストールする必要がある","bash/POSIX構文のみに対応","Windows CMDおよびPowerShell構文と互換性がない"],"ko":["윈도우에 Git Bash 설치가 필요","bash/POSIX 구문만対応","윈도우 CMD 및 PowerShell 구문과 호환되지 않음"],"es":["Requiere la instalación de Git Bash en Windows","Limitado a la sintaxis bash/POSIX","Incompatible con la sintaxis de Windows CMD y PowerShell"],"fr":["Nécessite l''installation de Git Bash sur Windows","Limité à la syntaxe bash/POSIX","Incompatible avec la syntaxe de Windows CMD et PowerShell"],"de":["Benötigt die Installation von Git Bash auf Windows","Begrenzt auf die bash/POSIX-Syntax","Nicht kompatibel mit der Syntax von Windows CMD und PowerShell"],"pt":["Requer instalação do Git Bash no Windows","Limitado à sintaxe bash/POSIX","Incompatível com a sintaxe do Windows CMD e PowerShell"],"ru":["Требует установки Git Bash в Windows","Ограничен синтаксисом bash/POSIX","Несовместим с синтаксисом Windows CMD и PowerShell"],"ar":["يتطلب تثبيت Git Bash على Windows","محدود بناء جملة bash/POSIX","غير متوافق مع بناء جملة Windows CMD و PowerShell"]},"version":3},"qualityScore":35}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mattgierhart/PRD-driven-context-engineering/ghm-gate-check', 'community', 'mattgierhart', 'PRD-driven-context-engineering', 'mattgierhart/PRD-driven-context-engineering', 'ghm-gate-check', 0, 0, 50, '2026-02-18T01:08:43.460Z', '2026-02-18T07:48:12.707Z', NULL, '{"id":"mattgierhart/PRD-driven-context-engineering/ghm-gate-check","name":"ghm-gate-check","description":{"zh":"GHM-Gate-Check是一种系统方法，用于开发AI产品，通过验证门槛标准和评估交接要求，确保产品的有效性和效率","ja":"GHM-Gate-CheckはAI製品開発のための体系的な方法で、ゲート基準の検証とハンドオフ要件の評価を通じて、製品の有効性と効率を確保します","ko":"GHM-Gate-Check는 AI 제품 개발을 위한 체계적인 방법으로 게이트 기준의 검증과 핸드오버 요구사항의 평가를 통해 제품의 유효성과 효율성을 보장합니다","es":"ghm-gate-check es una solución de ingeniería de contexto que valida los requisitos de desarrollo para productos AI. Optimiza tus flujos de trabajo y productos","fr":"ghm-gate-check est une solution d''ingénierie de contexte qui valide les exigences de développement pour les produits IA. Optimisez vos flux de travail et produits","de":"ghm-gate-check ist eine Kontext-Engineering-Lösung, die die Entwicklungsanforderungen für KI-Produkte überprüft. Optimieren Sie Ihre Arbeitsabläufe und Produkte","pt":"A verificação de portão GHM é uma abordagem sistemática para construir produtos de IA usando documentação progressiva e fluxos de trabalho de desenvolvimento cientes de contexto","ru":"Контроль шлюза GHM - это системный подход к созданию продуктов ИИ с использованием прогрессивной документации и контекстно-ориентированных рабочих процессов разработки","ar":"فحص بوابة GHM هو نهج منهجي لإنشاء منتجات ذكاء اصطناعي باستخدام توثيق تقدمي وعمليات عمل تطوير مدركة للسياق","en":"PRD-driven Context Engineering: A systematic approach to building AI-powered products using progressive documentation and context-aware development workflows"},"seo":{"title":{"zh":"GHM-Gate-Check：AI产品开发的系统方法","ja":"GHM-Gate-Check：AI製品開発の体系的なア