INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Bush2021/ayugram/task-think', 'community', 'Bush2021', 'ayugram', 'Bush2021/ayugram', 'task-think', 0, 0, 75, '2026-02-18T01:08:43.463Z', '2026-02-18T08:04:15.271Z', NULL, '{"id":"Bush2021/ayugram/task-think","name":"task-think","description":{"zh":"Task Think 技术允许开发人员运行全面的实现工作流程，附带仓库构件和清晰的阶段边界","ja":"Task Think 技術により、開発者はリポジトリ・アーティファクトと明確なフェーズの境界を持つ実装ワークフローを実行できます","ko":"Task Think 기술을 통해 개발자는 저장소 아티팩트와 명확한 단계 경계가 있는 구현 워크 플로우를 실행할 수 있습니다","es":"La tarea de pensamiento ejecuta un flujo de trabajo de implementación completo con artefactos de repositorio y límites de fase claros.","fr":"La tâche de réflexion exécute un workflow d''implémentation complet avec des artefacts de référentiel et des limites de phase claires.","de":"Die Aufgaben-Think-Funktion führt einen vollständigen Implementierungs-Workflow mit Repository-Artefakten und klaren Phasengrenzen aus.","pt":"O Task-Think é uma ferramenta que permite executar um fluxo de trabalho completo com artefatos de repositório e limites de fase claros.","ru":"Task-Think - это инструмент, позволяющий выполнить полный рабочий процесс с артефактами репозитория и четкими границами фаз.","ar":"Task-Think هو أداة تمكنك من تنفيذ تدفق عمل كامل مع فنون مخزن وحدود مرحلة واضحة.","en":"https://github.com/AyuGram/AyuGramDesktop/commits/dev/"},"seo":{"title":{"zh":"任务流水线 - Task Think 技术","ja":"タスクパイプライン - Task Think 技術","ko":"태스크 파이프라인 - Task Think 기술","es":"Tarea de pensamiento: flujo de trabajo de implementación","fr":"Tâche de réflexion : workflow d''implémentation","de":"Aufgaben-Think: Implementierungs-Workflow","pt":"Task-Think: Pipeline de Tarefas para Desenvolvedores","ru":"Task-Think: Конвейер задач для разработчиков","ar":"Task-Think: труб#line لتنفيذ المهام للمطورين","en":"task-think"},"description":{"zh":"Task Think 技术允许开发人员运行全面的实现工作流程，附带仓库构件和清晰的阶段边界","ja":"Task Think 技術により、開発者はリポジトリ・アーティファクトと明確なフェーズの境界を持つ実装ワークフローを実行できます","ko":"Task Think 기술을 통해 개발자는 저장소 아티팩트와 명확한 단계 경계가 있는 구현 워크 플로우를 실행할 수 있습니다","es":"La tarea de pensamiento ejecuta un flujo de trabajo de implementación completo con artefactos de repositorio y límites de fase claros.","fr":"La tâche de réflexion exécute un workflow d''implémentation complet avec des artefacts de référentiel et des limites de phase claires.","de":"Die Aufgaben-Think-Funktion führt einen vollständigen Implementierungs-Workflow mit Repository-Artefakten und klaren Phasengrenzen aus.","pt":"O Task-Think é uma ferramenta que permite executar um fluxo de trabalho completo com artefatos de repositório e limites de fase claros.","ru":"Task-Think - это инструмент, позволяющий выполнить полный рабочий процесс с артефактами репозитория и четкими границами фаз.","ar":"Task-Think هو أداة تمكنك من تنفيذ تدفق عمل كامل مع فنون مخزن وحدود مرحلة واضحة.","en":"https://github.com/AyuGram/AyuGramDesktop/commits/dev/"},"definition":{"en":"https://github.com/AyuGram/AyuGramDesktop/commits/dev/"},"features":{"zh":["运行全面的实现工作流程","附带仓库构件","清晰的阶段边界","支持任务描述和可选项目名称","支持可选约束和截图路径"],"ja":["実装ワークフローを実行","リポジトリ・アーティファクトを付加","明確なフェーズの境界","タスクの説明とオプションのプロジェクト名をサポート","オプションの制約とスクリーンショットのパスをサポート"],"ko":["구현 워크 플로우를 실행","저장소 아티팩트를 첨부","명확한 단계 경계","작업 설명 및 선택적 프로젝트 이름을 지원","선택적 제약 및 스크린샷 경로를 지원"],"es":["Ejecuta un flujo de trabajo de implementación completo","Utiliza artefactos de repositorio","Establece límites de fase claros","Permite la ingesta de descripciones de tareas","Admite la creación de resúmenes textuales","Incluye la opción de adjuntar capturas de pantalla"],"fr":["Exécute un workflow d''implémentation complet","Utilise des artefacts de référentiel","Établit des limites de phase claires","Permet l''ingestion de descriptions de tâches","Prend en charge la création de résumés textuels","Inclut l''option d''ajouter des captures d''écran"],"de":["Führt einen vollständigen Implementierungs-Workflow aus","Verwendet Repository-Artefakte","Setzt klare Phasengrenzen","Ermöglicht die Eingabe von Aufgabenbeschreibungen","Unterstützt die Erstellung von Textzusammenfassungen","Beinhaltet die Option, Screenshots anzuhängen"],"pt":["Execução de fluxo de trabalho completo","Artefatos de repositório","Limites de fase claros","Coleta de descrição de tarefa","Suporte a projetos","Suporte a constraints"],"ru":["Выполнение полного рабочего процесса","Артефакты репозитория","Четкие границы фаз","Сбор описания задачи","Поддержка проектов","Поддержка ограничений"],"ar":["تنفيذ تدفق عمل كامل","فنون مخزن","حدود مرحلة واضحة","جمع وصف المهمة","دعم المشاريع","دعم القيود"]},"keywords":{"zh":["Task Think","任务流水线","实现工作流程","仓库构件","阶段边界","任务描述","项目名称","约束","截图路径"],"ja":["Task Think","タスクパイプライン","実装ワークフロー","リポジトリ・アーティファクト","フェーズの境界","タスクの説明","プロジェクト名","制約","スクリーンショットのパス"],"ko":["Task Think","태스크 파이프라인","구현 워크 플로우","저장소 아티팩트","단계 경계","작업 설명","프로젝트 이름","제약","스크린샷 경로"],"es":["tarea de pensamiento","flujo de trabajo de implementación","arte factos de repositorio","límites de fase","descripción de tareas","resúmenes textuales","capturas de pantalla","desarrollo de software","ingeniería de software"],"fr":["tâche de réflexion","workflow d''implémentation","artefacts de référentiel","limites de phase","descriptions de tâches","résumés textuels","captures d''écran","développement de logiciels","ingénierie de logiciels"],"de":["Aufgaben-Think","Implementierungs-Workflow","Repository-Artefakte","Phasengrenzen","Aufgabenbeschreibungen","Textzusammenfassungen","Screenshots","Software-Entwicklung","Software-Ingenieurwesen"],"pt":["task-think","pipeline de tarefas","desenvolvedores","fluxo de trabalho","repositório","fase","tarefa","projeto","constraints"],"ru":["task-think","конвейер задач","разработчики","рабочий процесс","репозиторий","фаза","задача","проект","ограничения"],"ar":["task-think","ترب#line لتنفيذ المهام","مطورين","تدفق عمل","مخزن","مرحلة","مهمة","مشروع","قيود"]}},"owner":"Bush2021","repo":"ayugram","repoPath":"Bush2021/ayugram","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.463Z","topics":[],"category":"community","skillMd":{"name":"task-think","description":"Orchestrate a multi-phase implementation workflow for this repository with artifact files under .ai/<project-name>/<letter>/ and optional fresh codex exec child runs per phase. Use when the user wants one prompt to drive context gathering, planning, implementation, verification, and review iterations while keeping the main session context clean.","bodyPreview":"# Task Pipeline\n\nRun a full implementation workflow with repository artifacts and clear phase boundaries.\n\n## Inputs\n\nCollect:\n- task description\n- optional project name (if missing, derive a short kebab-case name)\n- optional constraints (files, architecture, deadlines, risk tolerance)\n- optional screenshot paths\n\nIf screenshots are attached in UI but not present as files, write a brief textual summary in `.ai/<project-name>/about.md` so child runs can consume the requirements.\n\n## Overview\n\nThe","body":"# Task Pipeline\n\nRun a full implementation workflow with repository artifacts and clear phase boundaries.\n\n## Inputs\n\nCollect:\n- task description\n- optional project name (if missing, derive a short kebab-case name)\n- optional constraints (files, architecture, deadlines, risk tolerance)\n- optional screenshot paths\n\nIf screenshots are attached in UI but not present as files, write a brief textual summary in `.ai/<project-name>/about.md` so child runs can consume the requirements.\n\n## Overview\n\nThe workflow is organized around **projects**. Each project lives in `.ai/<project-name>/` and can contain multiple sequential **tasks** (labeled `a`, `b`, `c`, ... `z`).\n\nProject structure:\n```\n.ai/<project-name>/\n  about.md              # Single source of truth for the entire project\n  a/                    # First task\n    context.md          # Gathered codebase context for this task\n    plan.md             # Implementation plan\n    review.md           # Code review document\n  b/                    # Follow-up task\n    context.md\n    plan.md\n    review.md\n  c/                    # Another follow-up task\n    ...\n```\n\n- `about.md` is the project-level blueprint — a single comprehensive document describing what this project does and how it works, written as if everything is already fully implemented. It contains no temporal state (\"current state\", \"pending changes\", \"not yet implemented\"). It is **rewritten** (not appended to) each time a new task starts, incorporating the new task''s changes as if they were always part of the design.\n- Each task folder (`a/`, `b/`, ...) contains self-contained files for that task. The task''s `context.md` carries all task-specific information: what specifically needs to change, the delta from the current codebase, gathered file references and code patterns. Planning, implementation, and review agents only read the current task''s folder.\n\n## Artifacts\n\nCreate and maintain:\n- `.ai/<project-name>/about.md`\n- `.ai/<project-name>/<letter>/context.md`\n- `.ai/<project-name>/<letter>/plan.md`\n- `.ai/<project-name>/<letter>/implementation.md`\n- `.ai/<project-name>/<letter>/review.md`\n- `.ai/<project-name>/<letter>/logs/phase-*.jsonl` (when running child `codex exec`)\n\n## Execution Mode\n\nRun `codex exec --json` child sessions for each phase.\n\n## Fresh-Run Mode Procedure\n\n1. Detect follow-up vs new project (check if first token of task description matches an existing project name with `about.md`).\n2. For new projects: pick unique short name, create `.ai/<project-name>/` and `.ai/<project-name>/a/`.\n3. For follow-up tasks: find latest task letter, create `.ai/<project-name>/<next-letter>/`.\n4. Run child phase sessions sequentially, waiting for each to finish.\n5. After each phase, validate artifact file exists and has substantive content.\n6. Summarize status in the parent session after each phase.\n7. Stop immediately on blocking errors and report exact blocker.\n\nUse the phase prompt templates in `PROMPTS.md`.\n\n## Verification Rules\n\n- If build or test commands fail due to file locks or access-denied outputs, stop and ask the user to close locking processes before retrying.\n- Never claim completion without:\n  - implemented code changes present\n  - build/test attempt results recorded\n  - review pass documented with any follow-up fixes\n\n## Completion Criteria\n\nMark complete only when:\n- plan phases are done\n- verification results are recorded\n- review issues are addressed or explicitly deferred with rationale\n- Remind the user of the project name so they can request follow-up tasks within the same project.\n\n## User Invocation\n\nUse plain language with the skill name in the request, for example:\n\n`Use local task-think skill: make sure FileLoadTask::process does not create or read QPixmap on background threads; use QImage with ARGB32_Premultiplied instead.`\n\nFor follow-up tasks on an existing project:\n\n`Use local task-think skill: my-project also handle the case where the file is already cached`\n\nIf screenshots are relevant, include file paths in the same prompt.\n"},"lastSynced":"2026-02-18T08:04:15.271Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude Code and AutoGPT requiring structured task management with repository artifacts and phase boundaries.","zh":"适合于Claude Code和AutoGPT等需要结构化任务管理的AI代理，包括仓库工件和阶段边界。","ja":"Claude CodeやAutoGPTのような、構造化されたタスク管理とリポジトリ・アーティファクトおよびフェーズ境界を必要とするAIエージェントに最適です。","ko":"구조화된 작업 관리 및 저장소 아티팩트 및 단계 경계가 필요한 Claude Code 및 AutoGPT와 같은 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA como Claude Code y AutoGPT que requieren una gestión de tareas estructurada con artefactos de repositorio y límites de fase.","fr":"Idéal pour les agents IA comme Claude Code et AutoGPT nécessitant une gestion de tâches structurée avec des artefacts de référentiel et des limites de phase.","de":"Ideal für KI-Agents wie Claude Code und AutoGPT, die eine strukturierte Aufgabenverwaltung mit Repository-Artefakten und Phasengrenzen erfordern.","pt":"Ideal para agentes de IA como Claude Code e AutoGPT que requerem gerenciamento de tarefas estruturado com artefatos de repositório e limites de fase.","ru":"Идеально подходит для агентов ИИ, таких как Claude Code и AutoGPT, требующих структурированного управления задачами с артефактами репозитория и границами фаз.","ar":"مثالية لعمليات الوكيل الذكي مثل Claude Code و AutoGPT التي تتطلب إدارة مهام منظم مع أشياء مخزن وحدود المرحلة."},"recommendation":{"en":"Empowers agents to manage complex task pipelines with clear inputs, including task descriptions, project names, constraints, and screenshot paths, utilizing Markdown files like `.ai/<project-name>/about.md` for textual summaries and facilitating consumption by child runs.","zh":"赋予代理管理复杂任务管道的能力，包括清晰的输入，如任务描述、项目名称、约束和截图路径，利用Markdown文件（如`.ai/<项目名称>/about.md`）进行文本摘要，并方便子运行消耗。","ja":"エージェントに複雑なタスク・パイプラインを管理する能力を与え、タスクの説明、プロジェクト名、制約、スクリーンショットのパスなどの明確な入力を含め、`.ai/<プロジェクト名>/about.md`のようなMarkdownファイルを使用してテキストの要約を行い、子ランの消費を容易にします。","ko":"에이전트가 복잡한 작업 파이프라인을 관리할 수 있는 기능을 제공하며, 작업 설명, 프로젝트 이름, 제약 및 스크린샷 경로와 같은 명확한 입력을 포함하고, `.ai/<프로젝트 이름>/about.md`와 같은 Markdown 파일을 사용하여 텍스트 요약을 생성하여 자식 실행에서 사용할 수 있도록 합니다.","es":"Permite a los agentes gestionar flujos de trabajo de tareas complejas con entradas claras, incluyendo descripciones de tareas, nombres de proyectos, restricciones y rutas de capturas de pantalla, utilizando archivos Markdown como `.ai/<nombre-del-proyecto>/about.md` para resúmenes textuales y facilitando su consumo por parte de ejecuciones secundarias.","fr":"Permet aux agents de gérer des flux de travail de tâches complexes avec des entrées claires, notamment des descriptions de tâches, des noms de projets, des contraintes et des chemins de captures d''écran, en utilisant des fichiers Markdown comme `.ai/<nom-du-projet>/about.md` pour des résumés textuels et en facilitant leur consommation par des exécutions secondaires.","de":"Ermöglicht es Agenten, komplexe Aufgaben-Pipelines mit klaren Eingaben zu verwalten, einschließlich Aufgabenbeschreibungen, Projektname, Einschränkungen und Screenshot-Pfade, unter Verwendung von Markdown-Dateien wie `.ai/<projektname>/about.md` für textuelle Zusammenfassungen und erleichtert den Verzehr durch nachfolgende Ausführungen.","pt":"Habilita os agentes a gerenciar pipelines de tarefas complexas com entradas claras, incluindo descrições de tarefas, nomes de projetos, restrições e caminhos de telas, utilizando arquivos Markdown como `.ai/<nome-do-projeto>/about.md` para resumos textuais e facilitando o consumo por execuções filho.","ru":"Позволяет агентам управлять сложными потоками задач с четкими входными данными, включая описания задач, имена проектов, ограничения и пути к скриншотам, используя файлы Markdown, такие как `.ai/<имя-проекта>/about.md`, для текстовых сводок и облегчая потребление дочерними запусками.","ar":"تمكّن العميل من إدارة خطوط أنابيب المهام المعقدة مع الإدخالات الواضحة، بما في ذلك وصف المهام وأسماء المشاريع والقيود ومسارات الشاشة، باستخدام ملفات Markdown مثل `.ai/<اسم-المشروع>/about.md` من أجل الملخصات النصية وتسهيل الاستهلاك بواسطة التشغيلات الفرعية."},"useCases":{"en":["Automating task pipeline workflows","Generating project names in kebab-case format","Creating textual summaries for missing screenshot files"],"zh":["自动化任务管道工作流","以短横线格式生成项目名称","为缺失的截图文件生成文本摘要"],"ja":["タスク・パイプライン・ワークフローの自動化","ケバブ・ケース形式でプロジェクト名を生成する","スクリーンショットのないファイルのテキスト要約を生成する"],"ko":["작업 파이프라인 워크플로 자동화","케밥 케이스 형식으로 프로젝트 이름 생성","스크린샷이 없는 파일에 대한 텍스트 요약 생성"],"es":["Automatización de flujos de trabajo de tareas","Generación de nombres de proyectos en formato kebab-case","Creación de resúmenes textuales para archivos de captura de pantalla que faltan"],"fr":["Automatisation des flux de travail de tâches","Génération de noms de projets au format kebab-case","Création de résumés textuels pour les fichiers de capture d''écran manquants"],"de":["Automatisierung von Aufgaben-Pipelines","Generierung von Projektname im kebab-case-Format","Erstellung von textuellen Zusammenfassungen für fehlende Screenshot-Dateien"],"pt":["Automatizar fluxos de trabalho de pipelines de tarefas","Gerar nomes de projetos no formato kebab-case","Criar resumos textuais para arquivos de screenshot ausentes"],"ru":["Автоматизировать рабочие процессы потоков задач","Генерировать имена проектов в формате kebab-case","Создавать текстовые сводки для отсутствующих файлов скриншотов"],"ar":["تأتمتة تدفقات عمل خطوط أنابيب المهام","إنشاء أسماء للمشاريع بالتنسيق kebab-case","إنشاء ملخصات نصية لملفات الشاشة المفقودة"]},"limitations":{"en":["Requires access to repository artifacts","Needs ability to write Markdown files"],"zh":["需要访问仓库工件","需要写入Markdown文件的能力"],"ja":["リポジトリ・アーティファクトへのアクセスが必要","Markdownファイルを書き込む能力が必要"],"ko":["저장소 아티팩트에 대한 액세스가 필요합니다","Markdown 파일을 작성할 수 있는 능력이 필요합니다"],"es":["Requiere acceso a artefactos de repositorio","Necesita la capacidad de escribir archivos Markdown"],"fr":["Nécessite l''accès aux artefacts de référentiel","Nécessite la capacité d''écrire des fichiers Markdown"],"de":["Benötigt Zugriff auf Repository-Artefakte","Benötigt die Fähigkeit, Markdown-Dateien zu schreiben"],"pt":["Requer acesso a artefatos de repositório","Necessita capacidade de escrever arquivos Markdown"],"ru":["Требует доступа к артефактам репозитория","Требует возможности записи файлов Markdown"],"ar":["يتطلب الوصول إلى أشياء المخزن","يحتاج إلى القدرة على كتابة ملفات Markdown"]},"version":3},"qualityScore":75}');
