INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Mrgig7/Multi-Agent-Enterprise-CRM/datastore-redis', 'community', 'Mrgig7', 'Multi-Agent-Enterprise-CRM', 'Mrgig7/Multi-Agent-Enterprise-CRM', 'datastore-redis', 0, 0, 0, '2026-02-18T01:08:43.464Z', '2026-02-18T08:08:32.419Z', NULL, '{"id":"Mrgig7/Multi-Agent-Enterprise-CRM/datastore-redis","name":"datastore-redis","description":{"zh":"作为 Redis 体系结构师，了解如何设计高效的 Redis 系统以实现限速、缓存、分布式锁和会话状态管理","ja":"Redis アーキテクトとして、レート制限、キャッシュ、分散ロック、セッション状態の管理を実現するための効率的な Redis システムの設計方法を学ぶ","ko":"Redis 아키텍트로서 속도 제한, 캐싱, 분산 잠금 및 세션 상태 관리를 위한 효율적인 Redis 시스템 설계 방법을 알아보세요","es":"Diseña una arquitectura de Redis para tareas específicas como limitación de velocidad y almacenamiento en caché, evitando el almacenamiento de datos de origen.","fr":"Concevez une architecture Redis pour des tâches spécifiques comme la limitation de débit et le stockage en cache, en évitant le stockage de données de source.","de":"Entwerfen Sie eine Redis-Architektur für spezifische Aufgaben wie Rate Limiting und Zwischenspeicherung, während Sie das Speichern von Quelldaten vermeiden","pt":"Aprenda a projetar uma arquitetura Redis eficaz para desenvolvedores, incluindo estratégias de TTL, políticas de expiração e recuperação de falhas.","ru":"Узнайте, как спроектировать эффективную архитектуру Redis для разработчиков, включая стратегии TTL, политики истечения срока действия и восстановления после сбоев.","ar":"تعرف على كيفية تصميم هندسة ريديس فعالة للمطورين، بما في ذلك استراتيجيات TTL وسياسات الانتهاء والاستعادة من الفشل.","en":"🤖 AI-Native Enterprise CRM with autonomous agents for sales, support, and compliance. Built with LangGraph, Kafka, Next.js, and Ollama. Features event-driven architecture, multi-tenant security, and human-in-the-loop AI governance."},"seo":{"title":{"zh":"Redis 数据存储最佳实践","ja":"Redis データストアの設計","ko":"Redis 데이터 저장소 설계","es":"Arquitectura de Redis para datastore","fr":"Conception de Redis pour datastore","de":"Redis-Architektur für datastore","pt":"Arquitetura Redis: Melhores Práticas para Desenvolvedores","ru":"Архитектура Redis: Лучшие Практики для Разработчиков","ar":"هندسة ريديس: أفضل الممارسات للمطورين","en":"datastore-redis"},"description":{"zh":"作为 Redis 体系结构师，了解如何设计高效的 Redis 系统以实现限速、缓存、分布式锁和会话状态管理","ja":"Redis アーキテクトとして、レート制限、キャッシュ、分散ロック、セッション状態の管理を実現するための効率的な Redis システムの設計方法を学ぶ","ko":"Redis 아키텍트로서 속도 제한, 캐싱, 분산 잠금 및 세션 상태 관리를 위한 효율적인 Redis 시스템 설계 방법을 알아보세요","es":"Diseña una arquitectura de Redis para tareas específicas como limitación de velocidad y almacenamiento en caché, evitando el almacenamiento de datos de origen.","fr":"Concevez une architecture Redis pour des tâches spécifiques comme la limitation de débit et le stockage en cache, en évitant le stockage de données de source.","de":"Entwerfen Sie eine Redis-Architektur für spezifische Aufgaben wie Rate Limiting und Zwischenspeicherung, während Sie das Speichern von Quelldaten vermeiden","pt":"Aprenda a projetar uma arquitetura Redis eficaz para desenvolvedores, incluindo estratégias de TTL, políticas de expiração e recuperação de falhas.","ru":"Узнайте, как спроектировать эффективную архитектуру Redis для разработчиков, включая стратегии TTL, политики истечения срока действия и восстановления после ...","ar":"تعرف على كيفية تصميم هندسة ريديس فعالة للمطورين، بما في ذلك استراتيجيات TTL وسياسات الانتهاء والاستعادة من الفشل.","en":"🤖 AI-Native Enterprise CRM with autonomous agents for sales, support, and compliance. Built with LangGraph, Kafka, Next.js, and Ollama. Features event-drive..."},"definition":{"en":"🤖 AI-Native Enterprise CRM with autonomous agents for sales, support, and compliance. Built with LangGraph, Kafka, Next.js, and Ollama. Features event-driven architecture, multi-tenant security, and human-in-the-loop AI governance."},"features":{"zh":["限速","缓存","分布式锁","会话状态管理","TTL 策略","驱逐策略"],"ja":["レート制限","キャッシュ","分散ロック","セッション状態の管理","TTL 戦略","追い出し戦略"],"ko":["속도 제한","캐싱","분산 잠금","세션 상태 관리","TTL 전략","추출 전략"],"es":["Limitación de velocidad","Almacenamiento en caché efímero","Candados distribuidos","Estado de sesión"],"fr":["Limitation de débit","Stockage en cache éphémère","Verrous distribués","État de session"],"de":["Rate Limiting","Flüchtiger Zwischenspeicher","Verteilte Sperren","Sitzungsstatus"],"pt":["Rate limiting","Cache efêmero","Travas distribuídas","Estado de sessão","Estratégias de TTL","Políticas de expiração"],"ru":["Ограничение скорости","Временный кэш","Распределенные замки","Состояние сессии","Стратегии TTL","Политики истечения срока действия"],"ar":["تحديد معدل","ذاكرة التخزين المؤقت المؤقتة","أقفال موزعة","حالة الجلسة","استراتيجيات TTL","سياسات الانتهاء"]},"keywords":{"zh":["Redis","数据存储","限速","缓存","分布式锁","会话状态管理","TTL","驱逐策略"],"ja":["Redis","データストア","レート制限","キャッシュ","分散ロック","セッション状態の管理","TTL","追い出し戦略"],"ko":["Redis","데이터 저장소","속도 제한","캐싱","분산 잠금","세션 상태 관리","TTL","추출 전략"],"es":["Redis","arquitectura de Redis","limitación de velocidad","almacenamiento en caché","candados distribuidos","estado de sesión","desarrollo de software"],"fr":["Redis","architecture Redis","limitation de débit","stockage en cache","verrous distribués","état de session","développement de logiciels"],"de":["Redis","Redis-Architektur","Rate Limiting","Zwischenspeicher","verteilte Sperren","Sitzungsstatus","Softwareentwicklung"],"pt":["arquitetura redis","desenvolvedores","rate limiting","cache efêmero","travas distribuídas","estado de sessão","estratégias de ttl","políticas de expiração"],"ru":["архитектура redis","разработчики","ограничение скорости","временный кэш","распределенные замки","состояние сессии","стратегии ttl","политики истечения срока действия"],"ar":["هندسة ريديس","مطورين","تحديد معدل","ذاكرة التخزين المؤقت المؤقتة","أقفال موزعة","حالة الجلسة","استراتيجيات ttl","سياسات الانتهاء"]}},"owner":"Mrgig7","repo":"Multi-Agent-Enterprise-CRM","repoPath":"Mrgig7/Multi-Agent-Enterprise-CRM","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.464Z","topics":[],"category":"community","skillMd":{"name":"datastore-redis","description":"Designs Redis usage for caching, rate limiting, and distributed locks.","bodyPreview":"You are a Redis architect.\n\nUse Redis only for:\n\n- Rate limiting\n- Ephemeral cache\n- Distributed locks\n- Session state\n\nNever store source of truth.\n\nExplain:\n\n- Key design\n- TTL strategy\n- Eviction policies\n- Failure recovery","body":"You are a Redis architect.\n\nUse Redis only for:\n\n- Rate limiting\n- Ephemeral cache\n- Distributed locks\n- Session state\n\nNever store source of truth.\n\nExplain:\n\n- Key design\n- TTL strategy\n- Eviction policies\n- Failure recovery\n"},"lastSynced":"2026-02-18T08:08:32.419Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, and Claude Code needing high-performance, in-memory data storage solutions with Redis for ephemeral caching and rate limiting.","zh":"适用于像Cursor、Windsurf和Claude Code这样的AI代理，需要高性能的内存数据存储解决方案，使用Redis进行临时缓存和限速。","ja":"Cursor、Windsurf、Claude CodeなどのAIエージェントに適しています。Redisを使用した一時的なキャッシュとレート制限のための、高性能なインメモリデータストレージソリューションが必要です。","ko":"커서, 윈드서핑, 클로드 코드와 같은 AI 에이전트에 적합합니다. 레디스를 사용한 임시 캐싱 및 속도 제한을 위한 고성능 인메모리 데이터 저장 솔루션이 필요합니다.","es":"Ideal para agentes de IA como Cursor, Windsurf y Claude Code que necesitan soluciones de almacenamiento de datos de alto rendimiento y en memoria con Redis para caché efímero y limitación de velocidad.","fr":"Idéal pour les agents IA comme Cursor, Windsurf et Claude Code ayant besoin de solutions de stockage de données haute performance et en mémoire avec Redis pour un cache éphémère et une limitation de débit.","de":"Ideal für KI-Agents wie Cursor, Windsurf und Claude Code, die hochleistungsfähige, im Speicher gespeicherte Datenlösungen mit Redis für ephemeres Caching und Ratenbegrenzung benötigen.","pt":"Ideal para Agentes de IA como Cursor, Windsurf e Claude Code que necessitam de soluções de armazenamento de dados de alto desempenho e na memória com Redis para cache efêmero e limitação de taxa.","ru":"Идеально подходит для агентов ИИ, таких как Cursor, Windsurf и Claude Code, которым требуются высокопроизводительные решения для хранения данных в памяти с Redis для эфемерного кэширования и ограничения скорости.","ar":"مثالية لعمليات الوكيل الذكي مثل Cursor و Windsurf و Claude Code التي تحتاج إلى حلول تخزين بيانات عالية الأداء في الذاكرة مع Redis للแคش المؤقت والتحكم في معدل النقل."},"recommendation":{"en":"Empowers agents to implement efficient rate limiting, ephemeral caching, and distributed locking mechanisms using Redis, ensuring scalable and secure data management with TTL strategy and eviction policies like ''volatile-lru'' and ''volatile-ttl'' for optimal performance.","zh":"赋予代理实现高效的限速、临时缓存和分布式锁定机制的能力，使用Redis确保可扩展和安全的数据管理，采用TTL策略和驱逐策略，如''volatile-lru''和''volatile-ttl''，以实现最佳性能。","ja":"Redisを使用して、エージェントが効率的なレート制限、一時的なキャッシュ、分散ロックメカニズムを実装できるようにします。TTL戦略と、''volatile-lru''および''volatile-ttl''などの追い出しポリシーを使用して、スケーラブルでセキュアなデータ管理を実現し、最適なパフォーマンスを実現します。","ko":"에이전트가 레디스를 사용하여 효율적인 속도 제한, 임시 캐싱 및 분산 잠금 메커니즘을 구현할 수 있도록 합니다. TTL 전략 및 ''volatile-lru'' 및 ''volatile-ttl''와 같은 추출 정책을 사용하여 확장 가능하고 보안이 강화된 데이터 관리를 보장하고 최적의 성능을 달성합니다.","es":"Permite a los agentes implementar mecanismos de limitación de velocidad eficientes, caché efímero y mecanismos de bloqueo distribuidos utilizando Redis, lo que garantiza una gestión de datos escalable y segura con estrategia TTL y políticas de expulsión como ''volatile-lru'' y ''volatile-ttl'' para un rendimiento óptimo.","fr":"Permet aux agents de mettre en œuvre des mécanismes de limitation de débit efficaces, un cache éphémère et des mécanismes de verrouillage distribués en utilisant Redis, garantissant ainsi une gestion de données scalable et sécurisée avec une stratégie TTL et des politiques d''éviction comme ''volatile-lru'' et ''volatile-ttl'' pour des performances optimales.","de":"Ermöglicht es den Agents, effiziente Ratenbegrenzungs-, ephemeres Caching- und verteilte Spermechanismen mit Redis umzusetzen, was eine skalierbare und sichere Datenverwaltung mit TTL-Strategie und Verdrängungsrichtlinien wie ''volatile-lru'' und ''volatile-ttl'' für optimale Leistung gewährleistet.","pt":"Permite que os agentes implementem mecanismos de limitação de taxa eficientes, cache efêmero e mecanismos de bloqueio distribuídos usando Redis, garantindo gerenciamento de dados escalável e seguro com estratégia TTL e políticas de expiração como ''volatile-lru'' e ''volatile-ttl'' para desempenho ótimo.","ru":"Позволяет агентам реализовывать эффективные механизмы ограничения скорости, эфемерное кэширование и распределенные механизмы блокировки с помощью Redis, обеспечивая масштабируемое и безопасное управление данными с помощью стратегии TTL и политик истечения срока действия, таких как ''volatile-lru'' и ''volatile-ttl'', для оптимальной производительности.","ar":"تمكن الوكيل من تنفيذ آليات تحكم في معدل النقل الفعالة والكاش المؤقت وآليات القفل الموزعة باستخدام Redis، مما يضمن إدارة بيانات قابلة للتوسعة وأمنية مع استراتيجية TTL وسياسات انتهاء الصلاحية مثل ''volatile-lru'' و ''volatile-ttl'' لأداء أمثل."},"useCases":{"en":["Implementing rate limiting for API requests","Caching frequently accessed data with TTL expiration","Managing distributed locks for concurrent operations"],"zh":["为API请求实现限速","使用TTL过期缓存频繁访问的数据","管理并发操作的分布式锁"],"ja":["APIリクエストのレート制限を実装する","TTL期限切れで頻繁にアクセスされるデータをキャッシュする","並行操作の分散ロックを管理する"],"ko":["API 요청에 대한 속도 제한 구현","TTL 만료로 빈번하게 액세스되는 데이터 캐싱","병렬 작업을 위한 분산 잠금 관리"],"es":["Implementar la limitación de velocidad para solicitudes de API","Almacenar en caché datos de acceso frecuente con expiración TTL","Administrar bloqueos distribuidos para operaciones concurrentes"],"fr":["Mettre en œuvre une limitation de débit pour les requêtes API","Mettre en cache des données fréquemment accessibles avec expiration TTL","Gérer des verrous distribués pour des opérations concurrentes"],"de":["Implementierung der Ratenbegrenzung für API-Anfragen","Speichern von häufig zugreifenden Daten im Cache mit TTL-Ablauf","Verwalten von verteilten Sperren für gleichzeitige Operationen"],"pt":["Implementação de limitação de taxa para solicitações de API","Armazenamento de dados de acesso frequente com expiração TTL","Gerenciamento de bloqueios distribuídos para operações concorrentes"],"ru":["Реализация ограничения скорости для запросов API","Кэширование часто доступных данных с истечением срока действия TTL","Управление распределенными блокировками для конкурирующих операций"],"ar":["تنفيذ آليات تحكم في معدل النقل لطلبات واجهة برمجة التطبيقات","تخزين البيانات التي يتم الوصول إليها بانتظام مع انتهاء صلاحية TTL","إدارة القفل الموزع للعمليات المتزامنة"]},"limitations":{"en":["Should not store source of truth data","Requires proper key design and TTL strategy for optimal performance","Needs failure recovery mechanisms in place"],"zh":["不应存储真实数据源","需要适当的键设计和TTL策略以实现最佳性能","需要在适当位置设置故障恢复机制"],"ja":["真実のデータソースを保存しないでください","最適なパフォーマンスを実現するには、適切なキーデザインとTTL戦略が必要です","適切な場所に障害復旧メカニズムを設定する必要があります"],"ko":["진실된 데이터 소스를 저장해서는 안됩니다","최적의 성능을 달성하려면 적절한 키 설계 및 TTL 전략이 필요합니다","적절한 위치에 장애 복구 메커니즘을 설정해야 합니다"],"es":["No debe almacenar datos de la fuente de la verdad","Requiere un diseño de clave y una estrategia TTL adecuados para un rendimiento óptimo","Necesita mecanismos de recuperación de fallos implementados"],"fr":["Ne doit pas stocker les données de la source de vérité","Nécessite une conception de clé et une stratégie TTL appropriées pour des performances optimales","Nécessite des mécanismes de récupération de défaillance en place"],"de":["Sollte keine Quelldaten speichern","Benötigt eine ordnungsgemäße Schlüsselgestaltung und TTL-Strategie für optimale Leistung","Benötigt im-vorfeld-eingerichtete Ausfallwiederherstellungsmechanismen"],"pt":["Não deve armazenar dados de origem","Requer projeto de chave apropriado e estratégia TTL para desempenho ótimo","Necessita de mecanismos de recuperação de falhas"],"ru":["Не должно хранить исходные данные","Требует правильного проектирования ключей и стратегии TTL для оптимальной производительности","Требует наличия механизмов восстановления после сбоя"],"ar":["لا ينبغي تخزين مصدر البيانات","يتطلب تصميم مفتاح مناسب و استراتيجية TTL من أجل الأداء الأمثل","يحتاج إلى آليات استعادة الفشل"]},"version":3},"qualityScore":0}');
