INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('CheekyCodexConjurer/quant-lab/refactor_gate', 'community', 'CheekyCodexConjurer', 'quant-lab', 'CheekyCodexConjurer/quant-lab', 'refactor_gate', 0, 0, 0, '2026-02-18T01:08:43.464Z', '2026-02-18T08:10:33.088Z', NULL, '{"id":"CheekyCodexConjurer/quant-lab/refactor_gate","name":"refactor_gate","description":{"zh":"Refactor Gate 是一个用于确定是否继续量化研究重构的工具，确保高效的重构过程","ja":"Refactor Gate は、量化研究のリファクタリングを続行するかどうかを判断するためのツールです","ko":"Refactor Gate는 양적 연구 리팩터링을 계속할지 여부를 결정하는 도구입니다","es":"Refactor Gate es una herramienta que confirma si se debe continuar con la refactorización después de mapear. Permite a los usuarios decidir si empezar a refactorizar ahora o capturar ideas de refactorización.","fr":"Refactor Gate est un outil qui confirme si la refactorisation doit être poursuivie après avoir effectué une cartographie. Il permet aux utilisateurs de décider s''ils doivent commencer à refactoriser maintenant ou capturer des idées de refactorisation.","de":"Refactor Gate ist ein Werkzeug, das bestätigt, ob nach der Kartierung mit der Refactoring fortgefahren werden soll. Es ermöglicht Benutzern, zu entscheiden, ob sie jetzt mit der Refactoring beginnen oder Refactoring-Ideen erfassen sollen.","pt":"O Refactor Gate é uma ferramenta que ajuda a confirmar se deve continuar com a refatoração após o mapeamento, criando um fluxo de trabalho eficiente para pesquisa quantitativa e visualização","ru":"Refactor Gate - это инструмент, который помогает подтвердить, следует ли продолжать рефакторинг после картографирования, создавая эффективный рабочий процесс для количественных исследований и визуализации","ar":"Refactor Gate هو أداة تساعد على تأكيد ما إذا كان يجب الاستمرار في إعادة الهيكلة بعد الخريطة، مما يتيح إنشاء تدفق عمل فعال للبحث الكمي والتصوير","en":"AERA: local-first workstation for quantitative research, visualization, and backtesting."},"seo":{"title":{"zh":"Refactor Gate: 量化研究重构入口","ja":"Refactor Gate: 量化研究のリファクタリング エントリ ポイント","ko":"Refactor Gate: 양적 연구 리팩터링 입구","es":"Refactor Gate: Confirmación de refactorización en AERA","fr":"Refactor Gate : Confirmation de refactorisation dans AERA","de":"Refactor Gate: Bestätigung der Refactoring in AERA","pt":"Refatoração de Código com Refactor Gate","ru":"Рефакторинг Кода с Refactor Gate","ar":"إعادة هيكلة الكود مع Refactor Gate","en":"refactor_gate"},"description":{"zh":"Refactor Gate 是一个用于确定是否继续量化研究重构的工具，确保高效的重构过程","ja":"Refactor Gate は、量化研究のリファクタリングを続行するかどうかを判断するためのツールです","ko":"Refactor Gate는 양적 연구 리팩터링을 계속할지 여부를 결정하는 도구입니다","es":"Refactor Gate es una herramienta que confirma si se debe continuar con la refactorización después de mapear. Permite a los usuarios decidir si empezar a refa...","fr":"Refactor Gate est un outil qui confirme si la refactorisation doit être poursuivie après avoir effectué une cartographie. Il permet aux utilisateurs de décid...","de":"Refactor Gate ist ein Werkzeug, das bestätigt, ob nach der Kartierung mit der Refactoring fortgefahren werden soll. Es ermöglicht Benutzern, zu entscheiden, ...","pt":"O Refactor Gate é uma ferramenta que ajuda a confirmar se deve continuar com a refatoração após o mapeamento, criando um fluxo de trabalho eficiente para pes...","ru":"Refactor Gate - это инструмент, который помогает подтвердить, следует ли продолжать рефакторинг после картографирования, создавая эффективный рабочий процесс...","ar":"Refactor Gate هو أداة تساعد على تأكيد ما إذا كان يجب الاستمرار في إعادة الهيكلة بعد الخريطة، مما يتيح إنشاء تدفق عمل فعال للبحث الكمي والتصوير","en":"AERA: local-first workstation for quantitative research, visualization, and backtesting."},"definition":{"en":"AERA: local-first workstation for quantitative research, visualization, and backtesting."},"features":{"zh":["确定是否继续重构","创建和更新 PLANS.md 和 IMPACT.md","捕获重构想法并停止","简短的重构流程"],"ja":["リファクタリングを続行するかどうかを判断","PLANS.md と IMPACT.md を作成および更新","